import _ from 'lodash';

/** 解析「坚固木材×1, 藤蔓×2」类材料字符串 */
export function parseMaterialString(materials: string): Record<string, number> {
  if (!materials || /无（|无需|不需要/.test(materials)) {
    return {};
  }
  const result: Record<string, number> = {};
  for (const part of materials.split(/[,，、]/)) {
    const m = part.trim().match(/^(.+?)\s*[×xX]\s*(\d+(?:\.\d+)?)/);
    if (m) {
      result[m[1].trim()] = Number(m[2]);
    }
  }
  return result;
}

export function warehouseHasMaterials(
  materials: Record<string, number>,
  warehouse: Record<string, { 当前: number; 上限: number }>,
): boolean {
  if (_.isEmpty(materials)) {
    return true;
  }
  return _.every(materials, (need, name) => (warehouse[name]?.当前 ?? 0) >= need);
}

export function formatMaterialsRecord(materials: Record<string, number>): string {
  return _.entries(materials)
    .map(([name, qty]) => `${name}×${qty}`)
    .join('，');
}

/** 与工作队列卡片一致：逗号分隔 */
export function formatMaterialsCatalog(materials: Record<string, number>): string {
  return _.entries(materials)
    .map(([name, qty]) => `${name}×${qty}`)
    .join(', ');
}

export function scaleMaterialRecord(
  materials: Record<string, number>,
  quantity: number,
): Record<string, number> {
  return _.mapValues(materials, qty => qty * quantity);
}

export function scaleMaterialString(materials: string, quantity: number): string {
  if (quantity <= 1) {
    return materials;
  }
  return formatMaterialsCatalog(scaleMaterialRecord(parseMaterialString(materials), quantity));
}

export function scaleWorkHours(hours: number, quantity: number): number {
  return hours * quantity;
}

export function maxAffordableQuantityFromMaterials(
  materials: Record<string, number>,
  warehouse: Record<string, { 当前: number; 上限: number }>,
): number {
  if (_.isEmpty(materials)) {
    return 99;
  }
  let max = 99;
  for (const [name, need] of _.entries(materials)) {
    if (need <= 0) {
      continue;
    }
    const have = warehouse[name]?.当前 ?? 0;
    max = Math.min(max, Math.floor(have / need));
  }
  return Math.max(0, max);
}
