import type { Schema } from '../../../schema';
import {
  EMPTY_NPC_ACTION_RECORD,
  type NpcActionRecord,
} from '../../../constants/gradeSystem';

const SETTLEMENT_KINDS = new Set(['探索', '狩猎', '采集', '工作']);

function ensure_record(npc: { 行动履历?: NpcActionRecord }): NpcActionRecord {
  if (!npc.行动履历 || typeof npc.行动履历 !== 'object') {
    npc.行动履历 = { ...EMPTY_NPC_ACTION_RECORD };
  }
  return npc.行动履历;
}

function parse_participants(raw: string): string[] {
  return raw
    .split(/[、,，/]/)
    .map(part =>
      part
        .trim()
        .replace(/^\d+\s*名/, '')
        .replace(/(同行|无名)?族人|队员|成员/g, '')
        .trim(),
    )
    .filter(name => name.length >= 1 && name.length <= 8 && !/^\d+$/.test(name) && !/队$/.test(name));
}

function leader_from_subtitle(subtitle: string): string | undefined {
  const m = subtitle.match(/^([^带队·]+?)带队/);
  return m?.[1]?.trim();
}

function quality_bucket(quality: string): '大成功' | '失败' | null {
  if (/大成功|完美|超额/.test(quality)) return '大成功';
  if (/失败|空手|溃退|带伤/.test(quality)) return '失败';
  return null;
}

function bump_record(
  record: NpcActionRecord,
  kind: '探索' | '狩猎' | '采集' | '工作',
  quality: string,
  asLeader: boolean,
): void {
  record[kind] += 1;
  if (asLeader) record.带队 += 1;
  const bucket = quality_bucket(quality);
  if (bucket === '大成功') record.大成功 += 1;
  if (bucket === '失败') record.失败 += 1;
}

type ParsedSettlementMeta = {
  kind: '探索' | '狩猎' | '采集' | '工作';
  quality: string;
  participants: string[];
  leader?: string;
};

function parse_settlement_blocks(story: string): ParsedSettlementMeta[] {
  const blocks: ParsedSettlementMeta[] = [];
  const re = /(?:<|&lt;)settlement_card(?:>|&gt;)([\s\S]*?)(?:<|&lt;)\/settlement_card(?:>|&gt;)/gi;
  let match: RegExpExecArray | null;
  while ((match = re.exec(story)) !== null) {
    const block = match[1];
    const kind = block.match(/\[类型\|(探索|狩猎|采集|工作)\]/)?.[1];
    if (!kind || !SETTLEMENT_KINDS.has(kind)) continue;
    const quality = block.match(/\[品质\|([^\]]+)\]/)?.[1]?.trim() ?? '成功';
    const participate = block.match(/\[参与(?:人员)?\|([^\]]+)\]/)?.[1] ?? '';
    const subtitle = block.match(/\[副标题\|([^\]]+)\]/)?.[1] ?? '';
    blocks.push({
      kind,
      quality,
      participants: parse_participants(participate),
      leader: leader_from_subtitle(subtitle),
    });
  }
  return blocks;
}

/** 从 assistant 正文的 settlement_card 为参与具名 NPC 累计行动履历 */
export function sync_npc_action_records_from_story(stat: Schema, story: string): boolean {
  const blocks = parse_settlement_blocks(story);
  if (blocks.length === 0) return false;

  let changed = false;
  for (const block of blocks) {
    for (const name of block.participants) {
      const npc = stat.具名NPC[name] ?? stat.未收入兽耳娘[name];
      if (!npc) continue;
      bump_record(ensure_record(npc), block.kind, block.quality, block.leader === name);
      changed = true;
    }
  }

  if (changed) {
    console.info('[行动履历] 已根据 settlement_card 更新参与 NPC 计数');
  }
  return changed;
}

export function format_action_record_summary(record: NpcActionRecord | undefined): string {
  if (!record) return '尚无外出记录';
  const parts: string[] = [];
  if (record.狩猎) parts.push(`狩猎×${record.狩猎}`);
  if (record.采集) parts.push(`采集×${record.采集}`);
  if (record.探索) parts.push(`探索×${record.探索}`);
  if (record.工作) parts.push(`工作×${record.工作}`);
  if (record.带队) parts.push(`带队×${record.带队}`);
  if (record.大成功) parts.push(`大成功×${record.大成功}`);
  return parts.length ? parts.join(' · ') : '尚无外出记录';
}
