import type { Schema } from '../../../schema';
import { dailyFuelBurn, fuelHoursRemaining, isFireLit, resolveFirepitKey } from './campfire';
import { getAvailableFoodRations } from './survivalDashboard';

export const NARRATIVE_CORRECTION_MIN = -20;
export const NARRATIVE_CORRECTION_MAX = 20;
/** 世界书约定：AI 每楼对单项 _修正 的 delta 不得超过此值 */
export const NARRATIVE_CORRECTION_PER_REPLY_MAX = 8;

const FOOD_RESERVE_BONUS: Record<Schema['营地']['营地状态']['食物储备'], number> = {
  极度匮乏: 0,
  勉强果腹: 8,
  储备充足: 18,
};

const SHELTER_LEVEL_SCORE: Record<Schema['营地']['营地状态']['住所等级'], number> = {
  露宿: 0,
  简陋窝棚: 12,
  稳固聚落: 28,
  石砌聚落: 42,
  舰城生活区: 55,
};

function clampMetric(value: number): number {
  return _.clamp(Math.round(value), 0, 100);
}

function clampCorrection(value: number): number {
  return _.clamp(Math.round(value), NARRATIVE_CORRECTION_MIN, NARRATIVE_CORRECTION_MAX);
}

function foodDaysScore(foodDays: number): number {
  if (foodDays <= 0) return 8;
  if (foodDays < 1) return 18;
  if (foodDays < 2) return 28;
  if (foodDays < 5) return 42;
  if (foodDays < 10) return 58;
  if (foodDays < 20) return 72;
  return 85;
}

function buildingEnvironmentScore(buildings: Schema['营地']['当前建筑']): number {
  let score = 0;
  for (const building of _.values(buildings)) {
    const phase = building.建筑阶段 ?? '已建成';
    const state = building.状态 ?? '';
    if (phase === '受损' || /漏风|破损|漏雨|冰冷|熄灭/.test(state)) {
      score -= 6;
      continue;
    }
    if (phase === '建造中' || phase === '蓝图') {
      score -= 2;
      continue;
    }
    if (/稳定|完好|温|旺|加固/.test(state)) {
      score += 5;
    } else if (phase === '已建成') {
      score += 2;
    }
  }
  return score;
}

/** 温饱基准：口粮储备 + 食物档位 + 住所（过夜/存粮条件） */
export function compute_warmth_base(data: Schema): number {
  const population = data.营地.人口;
  const totalRations = getAvailableFoodRations(data);
  const foodDays = population > 0 ? totalRations / population : totalRations > 0 ? 99 : 0;

  let score = foodDaysScore(foodDays) * 0.62;
  score += FOOD_RESERVE_BONUS[data.营地.营地状态.食物储备] ?? 0;
  score += (SHELTER_LEVEL_SCORE[data.营地.营地状态.住所等级] ?? 0) * 0.28;

  return clampMetric(score);
}

/** 栖居基准：住所、建筑完好、篝火/燃料、防御与仓储环境 */
export function compute_shelter_base(data: Schema): number {
  const camp = data.营地;
  let score = (SHELTER_LEVEL_SCORE[camp.营地状态.住所等级] ?? 0) * 0.55;
  score += buildingEnvironmentScore(camp.当前建筑);

  const dailyBurn = dailyFuelBurn(camp.当前建筑);
  const fuelCurrent = camp.篝火燃料.当前;
  const firepitKey = resolveFirepitKey(camp.当前建筑);
  const firepit = firepitKey ? camp.当前建筑[firepitKey] : undefined;
  const fireLit = isFireLit(fuelCurrent, firepit?.状态);

  if (!fireLit || fuelCurrent <= 0) {
    score -= 22;
  } else {
    const hours = fuelHoursRemaining(fuelCurrent, dailyBurn);
    if (hours < 4) score -= 10;
    else if (hours < 12) score += 4;
    else score += 12;
  }

  score += camp.防御工事.耐久 * 0.12;
  score += camp.防御等级 * 3;
  score += camp.仓库等级 * 2.5;

  return clampMetric(score);
}

/** 向心力基准：温饱/栖居 + 防御与储备稳定性 */
export function compute_cohesion_base(data: Schema): number {
  const warmth = compute_warmth_base(data);
  const shelter = compute_shelter_base(data);
  const reserveBonus = FOOD_RESERVE_BONUS[data.营地.营地状态.食物储备] ?? 0;

  let score = warmth * 0.38 + shelter * 0.38;
  score += reserveBonus * 0.35;
  score += data.营地.防御等级 * 3.5;

  if (warmth < 20) score -= 8;
  if (shelter < 15) score -= 8;
  if (warmth >= 60 && shelter >= 50) score += 6;

  return clampMetric(score);
}

export type SurvivalMetricSnapshot = {
  温饱度_基准: number;
  温饱度_修正: number;
  温饱度: number;
  栖居度_基准: number;
  栖居度_修正: number;
  栖居度: number;
  向心力_基准: number;
  向心力_修正: number;
  向心力: number;
};

function composeMetric(base: number, correction: number): number {
  return clampMetric(base + correction);
}

/** 跨日时剧情修正向 0 回归（每跨一天每项最多减 3 点绝对值） */
export function decay_narrative_corrections(data: Schema, day_delta: number): boolean {
  if (day_delta <= 0) return false;
  let changed = false;
  const step = 3 * day_delta;
  const metrics = data.营地.生存指标;

  for (const key of ['温饱度_修正', '栖居度_修正'] as const) {
    const prev = metrics[key];
    const next = clampCorrection(
      prev + (prev > 0 ? -Math.min(step, prev) : prev < 0 ? Math.min(step, -prev) : 0),
    );
    if (next !== prev) {
      metrics[key] = next;
      changed = true;
    }
  }

  const cohesionPrev = data.营地.向心力_修正;
  const cohesionNext = clampCorrection(
    cohesionPrev +
      (cohesionPrev > 0 ? -Math.min(step, cohesionPrev) : cohesionPrev < 0 ? Math.min(step, -cohesionPrev) : 0),
  );
  if (cohesionNext !== cohesionPrev) {
    data.营地.向心力_修正 = cohesionNext;
    changed = true;
  }

  return changed;
}

/**
 * 据公式基准 + 剧情修正重算三项显示值，并写回 _基准 供 AI/EJS 读取。
 * @returns 是否发生了变更
 */
export function sync_survival_metrics(data: Schema): boolean {
  const camp = data.营地;
  const metrics = camp.生存指标;

  metrics.温饱度_修正 = clampCorrection(metrics.温饱度_修正 ?? 0);
  metrics.栖居度_修正 = clampCorrection(metrics.栖居度_修正 ?? 0);
  camp.向心力_修正 = clampCorrection(camp.向心力_修正 ?? 0);

  const warmthBase = compute_warmth_base(data);
  const shelterBase = compute_shelter_base(data);
  const cohesionBase = compute_cohesion_base(data);

  const next = {
    温饱度_基准: warmthBase,
    温饱度: composeMetric(warmthBase, metrics.温饱度_修正),
    栖居度_基准: shelterBase,
    栖居度: composeMetric(shelterBase, metrics.栖居度_修正),
    向心力_基准: cohesionBase,
    向心力: composeMetric(cohesionBase, camp.向心力_修正),
  };

  let changed = false;
  if (metrics.温饱度_基准 !== next.温饱度_基准) {
    metrics.温饱度_基准 = next.温饱度_基准;
    changed = true;
  }
  if (metrics.温饱度 !== next.温饱度) {
    metrics.温饱度 = next.温饱度;
    changed = true;
  }
  if (metrics.栖居度_基准 !== next.栖居度_基准) {
    metrics.栖居度_基准 = next.栖居度_基准;
    changed = true;
  }
  if (metrics.栖居度 !== next.栖居度) {
    metrics.栖居度 = next.栖居度;
    changed = true;
  }
  if (camp.向心力_基准 !== next.向心力_基准) {
    camp.向心力_基准 = next.向心力_基准;
    changed = true;
  }
  if (camp.向心力 !== next.向心力) {
    camp.向心力 = next.向心力;
    changed = true;
  }

  return changed;
}

export function format_survival_metrics_hint(data: Schema): string {
  const m = data.营地.生存指标;
  const c = data.营地;
  return (
    `【生存指标】温饱 ${m.温饱度}（基准 ${m.温饱度_基准}${m.温饱度_修正 >= 0 ? '+' : ''}${m.温饱度_修正}）` +
    ` · 栖居 ${m.栖居度}（基准 ${m.栖居度_基准}${m.栖居度_修正 >= 0 ? '+' : ''}${m.栖居度_修正}）` +
    ` · 向心力 ${c.向心力}（基准 ${c.向心力_基准}${c.向心力_修正 >= 0 ? '+' : ''}${c.向心力_修正}）` +
    `；AI 仅可 patch *_修正（±${NARRATIVE_CORRECTION_PER_REPLY_MAX}/楼，累计 ±${NARRATIVE_CORRECTION_MAX}），禁止直接改显示值`
  );
}
