import type { Schema } from '../../../schema';
import { ERA_INFO } from '../../../constants/era';
import {
  dailyFuelBurn,
  formatFuelDuration,
  fuelHoursRemaining,
  hasWindproofFirepit,
} from './campfire';
import { getSurvivalEventCountdowns } from './survivalEventCountdown';

export type SurvivalWarningLevel = 'danger' | 'warn' | 'info';

export type SurvivalWarning = {
  level: SurvivalWarningLevel;
  text: string;
};

type FoodStock = { name: string; amount: number; rationsPerUnit: number };

/** 1 单位食材可折算的标准口粮份数（见世界观_营地消耗与生存结算规则） */
function foodRationsPerUnit(name: string): number | null {
  if (/方便面|能量棒|蛋白棒|压缩饼干|营养肉罐头|罐头|压缩口粮|军用口粮|自热|口粮饼干/.test(name)) {
    return 1;
  }
  if (/风干肉/.test(name)) {
    return 2;
  }
  if (/生肉|烤肉|烟熏|熏肉|熟肉|肉条/.test(name)) {
    return 1;
  }
  if (/块茎|野果|菌菇|浆果|植物|果/.test(name)) {
    return 0.5;
  }
  return null;
}

function collectFoodStock(data: Schema): FoodStock[] {
  const stock: FoodStock[] = [];

  for (const [name, res] of Object.entries(data.营地.仓库储备)) {
    const rationsPerUnit = foodRationsPerUnit(name);
    if (rationsPerUnit && res.当前 > 0) {
      stock.push({ name, amount: res.当前, rationsPerUnit });
    }
  }

  for (const [name, item] of Object.entries(data.营地.物品栏)) {
    const rationsPerUnit = foodRationsPerUnit(name);
    if (rationsPerUnit && item.数量 > 0) {
      stock.push({ name, amount: item.数量, rationsPerUnit });
    }
  }

  return stock;
}

export function getDailyFoodDemand(population: number): number {
  return Math.max(0, population);
}

export function getAvailableFoodRations(data: Schema): number {
  return collectFoodStock(data).reduce((sum, item) => sum + item.amount * item.rationsPerUnit, 0);
}

function formatDaysRemaining(days: number): string {
  if (days <= 0) {
    return '不足 1 天';
  }
  if (days < 1.5) {
    return '约 1 天';
  }
  return `约 ${Math.floor(days)} 天`;
}

function resolveFoodStatus(
  foodDays: number,
  dailyDemand: number,
  totalRations: number,
): '充足' | '紧张' | '危急' | '断粮' {
  if (dailyDemand <= 0) {
    return '充足';
  }
  if (totalRations < dailyDemand) {
    return '断粮';
  }
  if (foodDays < 2) {
    return '危急';
  }
  if (foodDays < 5) {
    return '紧张';
  }
  return '充足';
}

function resolveFuelStatus(fuelHours: number, fuelCurrent: number): '充足' | '偏低' | '告急' | '熄灭' {
  if (fuelCurrent <= 0) {
    return '熄灭';
  }
  if (fuelHours < 4) {
    return '告急';
  }
  if (fuelHours < 12) {
    return '偏低';
  }
  return '充足';
}

type SurvivalDashboardCore = {
  dailyFoodDemand: number;
  totalFoodRations: number;
  foodDaysRemaining: number;
  foodDaysText: string;
  foodStatus: '充足' | '紧张' | '危急' | '断粮';
  foodReserveLabel: string;
  dailyFuelBurn: number;
  fuelHoursRemaining: number;
  fuelHoursText: string;
  fuelDaysRemaining: number;
  fuelDaysText: string;
  fuelStatus: '充足' | '偏低' | '告急' | '熄灭';
  windproofFirepit: boolean;
  fuelDailyNote: string;
};

export function buildSurvivalWarnings(data: Schema, view: SurvivalDashboardCore): SurvivalWarning[] {
  const warnings: SurvivalWarning[] = [];

  if (view.foodStatus === '断粮') {
    warnings.push({
      level: 'danger',
      text: `今日口粮不足：${view.dailyFoodDemand} 人需 ${view.dailyFoodDemand} 份，库存折合约 ${Math.floor(view.totalFoodRations)} 份，可能出现半额配给与温饱度下降`,
    });
  } else if (view.foodStatus === '危急') {
    warnings.push({
      level: 'danger',
      text: `食物仅够 ${view.foodDaysText}，请尽快狩猎、采集或烟熏存粮`,
    });
  } else if (view.foodStatus === '紧张') {
    warnings.push({
      level: 'warn',
      text: `食物储备 ${view.foodDaysText}，距离「储备充足」仍有差距，建议持续存粮`,
    });
  }

  if (view.fuelStatus === '熄灭') {
    warnings.push({
      level: 'danger',
      text: '公共火塘已熄灭：栖居度将受压，寒夜可能触发生病事件',
    });
  } else if (view.fuelStatus === '告急') {
    warnings.push({
      level: 'warn',
      text: `篝火燃料余量 ${view.fuelHoursText}，请尽快添柴`,
    });
  } else if (view.fuelStatus === '偏低') {
    warnings.push({
      level: 'info',
      text: `篝火尚可续 ${view.fuelHoursText}，留意夜间添柴`,
    });
  }

  if (data.世界.当前时代 === '一' && data.营地.生存指标.温饱度 < 60) {
    warnings.push({
      level: 'info',
      text: `温饱度 ${data.营地.生存指标.温饱度}% 未达演进表目标（≥60）`,
    });
  }

  if (data.世界.当前时代 === '一' && data.营地.营地状态.食物储备 !== '储备充足') {
    warnings.push({
      level: 'info',
      text: `营地食物状态「${data.营地.营地状态.食物储备}」，演进表要求「储备充足」`,
    });
  }

  return warnings;
}

export function getSurvivalDashboardView(data: Schema) {
  const dailyFoodDemand = getDailyFoodDemand(data.营地.人口);
  const totalFoodRations = getAvailableFoodRations(data);
  const foodDaysRemaining =
    dailyFoodDemand > 0 ? totalFoodRations / dailyFoodDemand : totalFoodRations > 0 ? 999 : 0;

  const dailyFuelBurnRate = dailyFuelBurn(data.营地.当前建筑);
  const fuelCurrent = data.营地.篝火燃料.当前;
  const fuelHours = fuelHoursRemaining(fuelCurrent, dailyFuelBurnRate);
  const fuelDaysRemaining = dailyFuelBurnRate > 0 ? fuelCurrent / dailyFuelBurnRate : 0;

  const partial = {
    dailyFoodDemand,
    totalFoodRations: Math.round(totalFoodRations * 10) / 10,
    foodDaysRemaining,
    foodDaysText: formatDaysRemaining(foodDaysRemaining),
    foodStatus: resolveFoodStatus(foodDaysRemaining, dailyFoodDemand, totalFoodRations),
    foodReserveLabel: data.营地.营地状态.食物储备,
    dailyFuelBurn: dailyFuelBurnRate,
    fuelHoursRemaining: fuelHours,
    fuelHoursText: fuelCurrent <= 0 ? '已熄灭' : formatFuelDuration(fuelHours),
    fuelDaysRemaining,
    fuelDaysText: formatDaysRemaining(fuelDaysRemaining),
    fuelStatus: resolveFuelStatus(fuelHours, fuelCurrent),
    windproofFirepit: hasWindproofFirepit(data.营地.当前建筑),
    fuelDailyNote: hasWindproofFirepit(data.营地.当前建筑)
      ? '石砌防风火塘：约 4 单位/日'
      : '露天火塘：约 10 单位/日',
  };

  return {
    ...partial,
    campOverview: {
      location: data.世界.当前位置,
      survivalDays: data.世界.生存天数,
      era: data.世界.当前时代,
      eraName: ERA_INFO[data.世界.当前时代].名称,
    },
    countdowns: getSurvivalEventCountdowns(data.世界.兽历),
    warnings: buildSurvivalWarnings(data, partial),
  };
}
