import type { Schema } from '../../../schema';
import type { WorkProject, WorkQueueType } from '../constants/workProjectCatalog';

const ONE_TIME_WORK_TYPES = new Set<WorkQueueType>(['学习', '研发']);

export function isOneTimeWorkType(type: WorkQueueType | string): boolean {
  return ONE_TIME_WORK_TYPES.has(type as WorkQueueType);
}

export function isRepeatableWorkType(type: WorkQueueType | string): boolean {
  return type === '生产';
}

export function isWorkProjectCompleted(project: WorkProject, unlocked_tech: string[]): boolean {
  if (!isOneTimeWorkType(project.type)) {
    return false;
  }
  return unlocked_tech.includes(project.name);
}

/** 学习/研发完工后写入【已解锁科技】，避免重复排队 */
export function unlockOneTimeWorkProject(data: Schema, project_name: string, work_type: string): void {
  if (!isOneTimeWorkType(work_type)) {
    return;
  }
  if (!data.已解锁科技.includes(project_name)) {
    data.已解锁科技.push(project_name);
  }
}

export function workProductionQuantity(work: Schema['工作队列'][string]): number {
  const qty = work.生产数量;
  if (qty == null || qty < 1) {
    return 1;
  }
  return qty;
}
