import type { Schema } from '../../../schema';
import { markStatusBarLocalMutation } from '@util/common';
import { syncAllWorkActivation } from './workQueue';
import { sync_work_queue_hours, reconcile_completed_work_queue } from './workQueueProgress';
import { sync_exploration_squads_time } from './explorationTimeProgress';
import { sync_tribal_affairs } from './tribalAffairsSync';
import {
  archive_completed_comprehensive_affairs,
  archive_settled_pending_affairs,
  backfill_affair_creation_dates,
} from './tribeLog';
import { estimateElapsedHours } from './worldClock';
import { decay_narrative_corrections, sync_survival_metrics } from './survivalMetricsSync';

export type WorldTick = { 生存天数: number; 时间: string };

let last_chat_id = '';
let last_message_id: number | undefined;
let last_tick: WorldTick | null = null;

export function estimate_work_hours(prev: WorldTick, curr: WorldTick): number {
  if (curr.生存天数 < prev.生存天数) {
    return 0;
  }
  const day_delta = curr.生存天数 - prev.生存天数;
  return estimateElapsedHours(prev.时间, curr.时间, day_delta);
}

function resolve_latest_message_id(): number | undefined {
  try {
    const msgs = getChatMessages(-1);
    return msgs[0]?.message_id;
  } catch {
    return undefined;
  }
}

function resolve_chat_id(): string {
  try {
    return SillyTavern.getCurrentChatId?.() ?? '';
  } catch {
    return '';
  }
}

function resolve_previous_world_tick(): WorldTick | null {
  try {
    const msgs = getChatMessages(-2);
    const stat = msgs[0]?.variables?.stat_data as { 世界?: Partial<WorldTick> } | undefined;
    if (!stat?.世界) {
      return null;
    }
    return {
      生存天数: Number(stat.世界.生存天数 ?? 0),
      时间: String(stat.世界.时间 ?? ''),
    };
  } catch {
    return null;
  }
}

export type TimeAdvance = {
  hours: number;
  prev: WorldTick;
  curr: WorldTick;
};

/** 检测自上次 tick 以来游戏时间推进了多少「有效工时」 */
export function detect_time_advance(data: Schema): TimeAdvance | null {
  const chat_id = resolve_chat_id();
  if (chat_id !== last_chat_id) {
    last_chat_id = chat_id;
    last_message_id = undefined;
    last_tick = null;
  }

  const curr: WorldTick = {
    生存天数: data.世界.生存天数,
    时间: data.世界.时间,
  };
  const message_id = resolve_latest_message_id();

  if (message_id !== last_message_id) {
    last_message_id = message_id;
    const prev_world = resolve_previous_world_tick();
    if (prev_world) {
      last_tick = prev_world;
    } else if (!last_tick) {
      last_tick = { ...curr };
      return null;
    }
  }

  if (!last_tick) {
    last_tick = { ...curr };
    return null;
  }

  const prev = { ...last_tick };
  const hours = estimate_work_hours(prev, curr);
  last_tick = { ...curr };

  if (hours <= 0) {
    return null;
  }

  return { hours, prev, curr };
}

/** 统一时间 tick：工作队列、探索编队、部族事务、综合事物归档 */
export function sync_world_time_tick(data: Schema): void {
  let changed = reconcile_completed_work_queue(data);
  const advance = detect_time_advance(data);
  changed = backfill_affair_creation_dates(data) || changed;

  if (advance) {
    const { hours, prev, curr } = advance;
    const day_delta = curr.生存天数 - prev.生存天数;
    if (day_delta > 0) {
      changed = decay_narrative_corrections(data, day_delta) || changed;
    }
    changed = sync_work_queue_hours(data, hours) || changed;
    changed = sync_exploration_squads_time(data, hours) || changed;
    changed = sync_tribal_affairs(data, prev) || changed;
  } else {
    changed = sync_tribal_affairs(data, null) || changed;
  }

  changed = archive_settled_pending_affairs(data) || changed;
  changed = archive_completed_comprehensive_affairs(data) || changed;
  changed = sync_survival_metrics(data) || changed;

  syncAllWorkActivation(data);

  if (!changed) {
    return;
  }

  markStatusBarLocalMutation(10000);
}
