import type { Schema } from '../../schema';
import { ensure_squad_return_pending_affair } from './explorationTimeProgress';
import {
  is_npc_at_camp,
  is_npc_on_return_settlement,
  npc_indicates_returned_to_camp,
  npc_indicates_still_outbound,
} from './squadNpcPresence';
import { computeOutboundPlanHours } from './worldClock';

type Stat = Schema;
type Squad = Schema['探索编队'][string];
type NamedNpc = Schema['具名NPC'][string];

const OUTBOUND_STATUSES = new Set<Squad['状态']>(['探索中', '采集中', '狩猎中']);
const OUTBOUND_TASK_RE = /探索|狩猎|采集|外出|带队|搜寻|追踪|出队/;

function extractStoryFromMessage(text: string): string {
  const m = text.match(/(?:<|&lt;)story(?:>|&gt;)([\s\S]*?)(?:<|&lt;)\/story(?:>|&gt;)/i);
  return m?.[1] ?? text;
}

function getLatestAssistantStoryText(): string {
  if (typeof getChatMessages !== 'function') {
    return '';
  }
  const msgs = getChatMessages('0-{{lastMessageId}}');
  const latestAssistant = [...msgs].reverse().find(m => m.role === 'assistant');
  if (!latestAssistant) {
    return '';
  }
  return extractStoryFromMessage(latestAssistant.message);
}

function member_returned_in_story(story: string, memberName: string): boolean {
  if (!story.includes(memberName)) return false;
  const escaped = memberName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(
    `${escaped}[^。\\n]{0,100}(?:返回|归来|回到|走进|走入|走到|冲进|冲到|赶到|砸在|领到|撤|跟随)[^。\\n]{0,60}(?:营地|火塘|火光|归)|` +
      `(?:最先|最后|随后|终于)[^。\\n]{0,50}${escaped}|` +
      `${escaped}[^。\\n]{0,80}火塘`,
  ).test(story);
}

function should_squad_return_from_story(squad: Squad, story: string): boolean {
  if (!story || squad.状态 === '待命' || !OUTBOUND_STATUSES.has(squad.状态)) {
    return false;
  }
  return story_indicates_squad_returned(squad, story);
}

/** 正文是否已描写该编队全部具名成员归营（不检查当前编队状态） */
export function story_indicates_squad_returned(squad: Squad, story: string): boolean {
  if (!story) return false;
  if (!/返回|归来|回到|归营|陆续|撤了回来/.test(story)) {
    return false;
  }
  if (squad.具名成员.length === 0) {
    return false;
  }
  return squad.具名成员.every(name => member_returned_in_story(story, name));
}

function squad_members_indicate_departed(stat: Stat, squad: Squad): boolean {
  if (squad.具名成员.length === 0) {
    return false;
  }
  return squad.具名成员.some(name => npc_indicates_still_outbound(stat.具名NPC[name]));
}

function repair_squad_departure(stat: Stat, squad: Squad): void {
  if (!squad.计划时长 || squad.计划时长 < 2) {
    squad.计划时长 = computeOutboundPlanHours(stat.世界.时间);
  }
  squad.出发于 = {
    生存天数: stat.世界.生存天数,
    时间: stat.世界.时间,
    兽历: stat.世界.兽历,
  };
  squad.已耗工时 = 0;
}

function outbound_status_for_kind(kind: SquadKind): Squad['状态'] {
  if (kind === '采集') return '采集中';
  if (kind === '狩猎') return '狩猎中';
  return '探索中';
}

/** 待命编队成员已全部外出执行任务时，按剧情/NPC 状态补写出发记录 */
function sync_idle_squads_to_outbound(stat: Stat): boolean {
  let changed = false;
  for (const [name, squad] of Object.entries(stat.探索编队)) {
    if (squad.状态 !== '待命' || squad.出发于) {
      continue;
    }
    const kind = squad_kind_from_squad(name, squad);
    if (!kind || squad.具名成员.length === 0) {
      continue;
    }
    const allOutbound = squad.具名成员.every(member => {
      const npc = stat.具名NPC[member];
      if (!npc_indicates_still_outbound(npc)) {
        return false;
      }
      const preferred = npc_preferred_squad_kind(npc);
      return preferred === null || preferred === kind;
    });
    if (!allOutbound) {
      continue;
    }
    squad.状态 = outbound_status_for_kind(kind);
    repair_squad_departure(stat, squad);
    changed = true;
    console.info('[探索编队] 成员已外出，补写出发:', name);
  }
  return changed;
}

function mark_squad_idle(stat: Stat, squadName: string, squad: Squad, reason: string): void {
  if (squad.状态 === '待命') return;
  if (!squad.出发于) {
    squad.状态 = '待命';
    squad.已耗工时 = 0;
    console.info('[探索编队]', reason, '→ 未出发，改待命:', squadName);
    return;
  }
  ensure_squad_return_pending_affair(stat, squadName, squad);
  squad.状态 = '待命';
  squad.已耗工时 = 0;
  delete squad.出发于;
  for (const name of squad.具名成员) {
    const npc = stat.具名NPC[name];
    if (!npc) continue;
    if (is_npc_at_camp(npc) || npc.当前位置 === '') {
      npc.当前位置 = '营地';
    }
    if (OUTBOUND_TASK_RE.test(npc.当前任务 ?? '') && !/清点|献宝|上交/.test(npc.当前任务 ?? '')) {
      npc.当前任务 = '归来清点';
    }
    if (npc.状态 === '外出') {
      npc.状态 = '疲惫';
    }
  }
  console.info('[探索编队]', reason, '→ 待命:', squadName);
}

function is_empty_squad(squad: Squad): boolean {
  return squad.具名成员.length === 0 && squad.无名队员数 <= 0;
}

/** 剧情推断自动生成的编队名（如「白·采集队」），玩家自定义名称不在此列 */
export function is_auto_inferred_squad_name(name: string): boolean {
  return /^.+·(采集|狩猎|探索)队$/.test(name) || /^(采集|狩猎|巡逻|探索)队_/.test(name);
}

const AI_DUPLICATE_SQUAD_RE = /^(采集|狩猎|探索)队_/;

function canonical_squad_name(kind: SquadKind): string {
  if (kind === '采集') return '采集队';
  if (kind === '狩猎') return '狩猎队';
  return '探索队';
}

/** 移除 AI patch 误 insert 的「狩猎队_春」等重复/空编队，巡逻队不属于探索编队 */
export function reconcile_ai_duplicate_squads(stat: Stat): boolean {
  let changed = false;
  const squads = stat.探索编队;

  for (const name of [...Object.keys(squads)]) {
    if (/^巡逻队_/.test(name)) {
      delete squads[name];
      changed = true;
      console.info('[探索编队] 已移除误建巡逻编队:', name);
      continue;
    }
    if (!AI_DUPLICATE_SQUAD_RE.test(name)) continue;

    const squad = squads[name];
    const kind = squad_kind_from_squad(name, squad);
    const canonical = kind ? squads[canonical_squad_name(kind)] : undefined;

    if (is_empty_squad(squad)) {
      delete squads[name];
      changed = true;
      console.info('[探索编队] 已移除 AI 误建空编队:', name);
      continue;
    }

    if (canonical) {
      canonical.具名成员 = _.uniq([...canonical.具名成员, ...squad.具名成员]);
      canonical.无名队员数 = Math.max(canonical.无名队员数, squad.无名队员数);
      delete squads[name];
      changed = true;
      console.info('[探索编队] 已合并重复编队:', name, '→', canonical_squad_name(kind!));
    }
  }
  return changed;
}

/** AI 未把「探索中」改回「待命」时，据具名成员位置/状态推断是否已归营 */
export function should_squad_return_idle(squad: Squad, stat: Stat): boolean {
  if (squad.状态 === '待命' || !OUTBOUND_STATUSES.has(squad.状态)) return false;
  if (is_empty_squad(squad)) return true;

  const named = squad.具名成员;
  if (named.length === 0) {
    // 仅无名队员的外出编队：不因空具名数组误判为已归营
    return false;
  }

  if (named.some(name => npc_indicates_still_outbound(stat.具名NPC[name]))) {
    return false;
  }
  return named.every(name => npc_indicates_returned_to_camp(stat.具名NPC[name]));
}

/**
 * 校正探索编队：归来后改待命；删除 AI 误 insert 的空编队。
 * @returns 是否发生了变更
 */
/** 最新 AI 正文已描写全队归来，但变量未 patch 时同步为待命并创建归来清点 */
export function sync_squads_from_return_story(stat: Stat): boolean {
  const story = getLatestAssistantStoryText();
  if (!story) return false;
  let changed = false;
  for (const [name, squad] of Object.entries(stat.探索编队)) {
    if (should_squad_return_from_story(squad, story)) {
      mark_squad_idle(stat, name, squad, '剧情已描写归来');
      changed = true;
    }
  }
  return changed;
}

export function reconcile_exploration_squads(stat: Stat): boolean {
  let changed = false;
  const squads = stat.探索编队;

  if (sync_idle_squads_to_outbound(stat)) {
    changed = true;
  }

  for (const [name, squad] of Object.entries(squads)) {
    if (OUTBOUND_STATUSES.has(squad.状态) && !squad.出发于) {
      if (squad_members_indicate_departed(stat, squad)) {
        repair_squad_departure(stat, squad);
        changed = true;
        console.info('[探索编队] 变量已标外出但缺出发于，已补写:', name);
      } else {
        squad.状态 = '待命';
        squad.已耗工时 = 0;
        changed = true;
        console.info('[探索编队] 未通过 UI/剧情出发，改待命:', name);
      }
    }
  }

  for (const [name, squad] of Object.entries(squads)) {
    if (squad.状态 !== '待命' && should_squad_return_idle(squad, stat)) {
      mark_squad_idle(stat, name, squad, '成员已归营');
      changed = true;
    }
  }

  for (const [name, squad] of Object.entries(squads)) {
    if (squad.状态 === '待命') continue;
    const kind = squad_kind_from_squad(name, squad);
    if (!kind) continue;
    const expected: Squad['状态'] =
      kind === '采集' ? '采集中' : kind === '狩猎' ? '狩猎中' : '探索中';
    if (squad.状态 !== expected) {
      squad.状态 = expected;
      changed = true;
      console.info('[探索编队] 按队名校正状态:', name, '→', expected);
    }
  }

  for (const name of _.keys(squads)) {
    const squad = squads[name];
    if (squad.状态 === '待命' && is_empty_squad(squad) && is_auto_inferred_squad_name(name)) {
      delete squads[name];
      changed = true;
      console.info('[探索编队] 已移除空编队:', name);
    }
  }

  if (reconcile_ai_duplicate_squads(stat)) {
    changed = true;
  }

  return changed;
}

type SquadKind = '采集' | '狩猎' | '探索';

function squad_kind_from_squad(name: string, squad: Squad): SquadKind | null {
  const nameMatch = name.match(/(?:^|·)(采集|狩猎|探索)队(?:_|$)/);
  if (nameMatch) return nameMatch[1] as SquadKind;
  if (squad.状态 === '采集中') return '采集';
  if (squad.状态 === '狩猎中') return '狩猎';
  if (squad.状态 === '探索中') return '探索';
  return null;
}

/** 据 NPC 当前任务判断应属哪类外出编队；留守/巡逻返回 null */
export function npc_preferred_squad_kind(npc: NamedNpc | undefined): SquadKind | null {
  if (!npc) return null;
  const task = (npc.当前任务 ?? '').trim();
  if (!task || task === '待指派' || /营地巡逻|守营|留守|看守|守夜/.test(task)) {
    return null;
  }
  if (/巡逻/.test(task) && !/外出/.test(task)) {
    return null;
  }
  if (/带领采集|外出采集|采集中|采集队|^采集$/.test(task)) return '采集';
  if (/带领狩猎|外出狩猎|狩猎中|狩猎队|^狩猎$/.test(task)) return '狩猎';
  if (/带领探索|外出探索|探索中|探索队|^探索$/.test(task)) return '探索';
  return null;
}

/**
 * 具名成员不可重复占用多支队伍。
 * 外出中的编队以成员表为准，不因 AI 任务文案非标准而剔除；归营判定以位置为主。
 */
export function reconcile_squad_member_exclusivity(stat: Stat): boolean {
  let changed = false;
  const squads = stat.探索编队;

  for (const [squadName, squad] of Object.entries(squads)) {
    const squadOutbound = OUTBOUND_STATUSES.has(squad.状态);

    // 待命编队以玩家/UI  roster 为准，不因 NPC 仍在营地或未标外出任务而清空
    if (!squadOutbound) {
      continue;
    }

    for (const member of [...squad.具名成员]) {
      const npc = stat.具名NPC[member];

      if (squadOutbound) {
        if (npc_indicates_still_outbound(npc)) {
          continue;
        }
        if (!npc_indicates_returned_to_camp(npc)) {
          continue;
        }
      }

      const preferred = npc_preferred_squad_kind(npc);
      const squadKind = squad_kind_from_squad(squadName, squad);

      if (preferred === null) {
        const onReturnAffair = is_npc_on_return_settlement(npc);
        if (squadOutbound || npc_indicates_still_outbound(npc) || onReturnAffair) {
          continue;
        }
        if (is_npc_at_camp(npc)) {
          squad.具名成员 = squad.具名成员.filter(m => m !== member);
          changed = true;
          console.info('[探索编队] 移除非外出成员:', member, '←', squadName);
        }
        continue;
      }
      if (squadKind && squadKind !== preferred && is_npc_at_camp(npc)) {
        squad.具名成员 = squad.具名成员.filter(m => m !== member);
        changed = true;
        console.info('[探索编队] 成员任务与编队类型不符，移除:', member, squadName);
      }
    }
  }

  const memberSquads = new Map<string, string[]>();
  for (const [squadName, squad] of Object.entries(squads)) {
    for (const member of squad.具名成员) {
      const list = memberSquads.get(member) ?? [];
      list.push(squadName);
      memberSquads.set(member, list);
    }
  }

  for (const [member, squadNames] of memberSquads) {
    if (squadNames.length <= 1) continue;
    const preferred = npc_preferred_squad_kind(stat.具名NPC[member]);
    let keep =
      squadNames.find(sn => OUTBOUND_STATUSES.has(squads[sn].状态)) ??
      squadNames.find(sn => {
        const k = squad_kind_from_squad(sn, squads[sn]);
        return k === preferred;
      }) ??
      squadNames[0];
    for (const sn of squadNames) {
      if (sn === keep) continue;
      const squad = squads[sn];
      if (squad.具名成员.includes(member)) {
        squad.具名成员 = squad.具名成员.filter(m => m !== member);
        changed = true;
        console.info('[探索编队] 具名成员不可重复，从', sn, '移除', member);
      }
    }
  }

  return changed;
}

/** 出发时同步更新具名成员的外出状态，避免与编队状态不一致 */
export function mark_squad_members_departed(
  stat: Stat,
  squad: Squad,
  mode: '探索' | '狩猎' | '采集',
  target_area: string,
): void {
  const task_label =
    mode === '探索' ? `探索：${target_area}` : mode === '狩猎' ? `外出狩猎：${target_area}` : `外出采集：${target_area}`;
  for (const name of squad.具名成员) {
    const npc = stat.具名NPC[name];
    if (!npc) continue;
    npc.当前任务 = task_label;
    npc.当前位置 = target_area;
    npc.状态 = '外出';
  }
}
