import { ensure_opening_status_placeholder } from '../../util/openingStatus';
import { isStatusBarLocalMutation } from '@util/common';
import { backfillNpcPanelsIfEmpty, purge_misclassified_named_npcs, syncNpcPanelsFromMessage } from '../../util/npcPanelSync';
import { applySquadInferToStat } from '../../util/squadInferSync';
import {
  reconcile_exploration_squads,
  reconcile_squad_member_exclusivity,
  sync_squads_from_return_story,
} from '../../界面/状态栏/util/squadSync';
import { inferCampfireFuelFromStory, syncFirepitWithFuel } from '../../界面/状态栏/util/campfire';
import {
  clampWarehouseReserves,
  extractStoryFromMessage,
  repairMisplacedWarehouse,
  syncWarehouseFromSettlementStory,
} from '../../界面/状态栏/util/settlementSync';
import { sync_comprehensive_affairs } from '../../util/comprehensiveAffairsSync';
import { reconcile_completed_work_queue } from '../../界面/状态栏/util/workQueueProgress';
import { syncAllWorkActivation } from '../../界面/状态栏/util/workQueue';
import { ensure_exploration_area_catalog } from '../../界面/状态栏/util/explorationAreaBackfill';
import { sync_npc_action_records_from_story } from '../../界面/状态栏/util/npcActionRecord';
import { sync_survival_metrics } from '../../界面/状态栏/util/survivalMetricsSync';
import { sync_user_warehouse_deposits } from '../../util/userWarehouseSync';
import { cascade_purge_squads_after_regenerate, purge_unauthorized_exploration_squads } from '../../util/squadAuthority';
import { apply_user_squad_commands } from '../../util/squadUserCommands';

function getSettlementSyncedFloors(): number[] {
  if (typeof getVariables !== 'function' || typeof getScriptId !== 'function') {
    return [];
  }
  const vars = getVariables({ type: 'script', script_id: getScriptId() }) as {
    settlementWarehouseSynced?: { floors?: number[] };
  };
  return vars.settlementWarehouseSynced?.floors ?? [];
}

function markSettlementSyncedFloor(message_id: number): void {
  if (typeof replaceVariables !== 'function' || typeof getScriptId !== 'function') {
    return;
  }
  const floors = getSettlementSyncedFloors();
  if (floors.includes(message_id)) return;
  replaceVariables(
    { settlementWarehouseSynced: { floors: [...floors, message_id] } },
    { type: 'script', script_id: getScriptId() },
  );
}

let syncing = false;

async function safeSync(message_id: number, options: { allowSquadCreate?: boolean } = {}) {
  if (syncing) {
    return;
  }
  syncing = true;
  try {
    await syncNpcPanelsFromMessage(message_id);
    await syncSquadsFromContext(message_id, options.allowSquadCreate ?? false);
  } catch (error) {
    console.error('[NPC面板同步] 失败', error);
  } finally {
    syncing = false;
  }
}

async function syncSquadsFromContext(message_id: number, allowCreate = false) {
  if (isStatusBarLocalMutation()) {
    return;
  }
  await waitGlobalInitialized('Mvu');
  const mvu_data = Mvu.getMvuData({ type: 'message', message_id });
  const stat = _.get(mvu_data, 'stat_data') as import('../../schema').Schema | undefined;
  if (!stat || typeof stat !== 'object') return;
  purge_unauthorized_exploration_squads(stat, message_id);
  applySquadInferToStat(stat, { allowCreate });
  apply_user_squad_commands(stat);
  sync_squads_from_return_story(stat);
  reconcile_exploration_squads(stat);
  reconcile_squad_member_exclusivity(stat);
  ensure_exploration_area_catalog(stat);
  sync_comprehensive_affairs(stat);
  reconcile_completed_work_queue(stat);
  syncAllWorkActivation(stat);
  purge_misclassified_named_npcs(stat as Record<string, unknown>);
  sync_user_warehouse_deposits(stat);
  inferCampfireFuelFromStory(stat.营地.当前建筑, stat.营地.篝火燃料);
  syncFirepitWithFuel(stat.营地.当前建筑, stat.营地.篝火燃料);
  sync_survival_metrics(stat);
  const msg = getChatMessages(message_id)[0];
  repairMisplacedWarehouse(stat);
  if (
    syncWarehouseFromSettlementStory(stat, extractStoryFromMessage(msg?.message ?? ''), {
      messageText: msg?.message ?? '',
      messageId: message_id,
      syncedFloors: getSettlementSyncedFloors(),
    })
  ) {
    markSettlementSyncedFloor(message_id);
  }
  clampWarehouseReserves(stat);
  sync_npc_action_records_from_story(stat, extractStoryFromMessage(msg?.message ?? ''));
  _.set(mvu_data, 'stat_data', stat);
  await Mvu.replaceMvuData(mvu_data, { type: 'message', message_id });
}

$(() => {
  errorCatched(async () => {
    await waitGlobalInitialized('Mvu');

    eventOn(tavern_events.GENERATION_ENDED, (message_id: number) => {
      const msgs = getChatMessages(message_id);
      const msg = msgs[0];
      const story = msg?.message ?? '';
      const allowSquadCreate =
        msg?.role === 'assistant' &&
        /(出发|外出|带队|率领|派遣|成立|新建编队|编队|分队|采集队|狩猎队|探索队|当.{0,12}队长|加入.{0,8}队).{0,16}(队|采集|狩猎|探索)/.test(
          story,
        );
      void (async () => {
        await safeSync(message_id, { allowSquadCreate });
        await cascade_purge_squads_after_regenerate(message_id);
      })();
      void ensure_opening_status_placeholder(message_id);
    });

    eventOn(tavern_events.MESSAGE_SWIPED, (message_id: number) => {
      void (async () => {
        await safeSync(message_id);
        await cascade_purge_squads_after_regenerate(message_id);
      })();
    });

    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
      const id = getCurrentMessageId();
      if (typeof id === 'number') {
        void ensure_opening_status_placeholder(id);
      }
    });

    const runStartupSync = async () => {
      await backfillNpcPanelsIfEmpty();
      await ensure_opening_status_placeholder();
      const latest = getChatMessages(-1, { role: 'assistant' })[0];
      if (latest) {
        await safeSync(latest.message_id);
      }
    };
    void runStartupSync();
    setTimeout(() => void runStartupSync(), 1500);
    setTimeout(() => void runStartupSync(), 4000);

    console.info('[NPC面板同步] 已加载');
  })();
});
