import type { Schema } from '../schema';
import { WORK_PROJECT_CATALOG } from '../界面/状态栏/constants/workProjectCatalog';

type Stat = Schema;

const CATALOG_NAMES = new Set(WORK_PROJECT_CATALOG.map(p => p.name));

const NON_WORK_QUEUE_NAME_RE =
  /营地巡逻|外围巡逻|营地警戒|营地守卫|营地放哨|^(日常)?巡逻$|放哨|守夜|守营|留守|看守/;

const PATROL_TASK_RE = /营地巡逻|外围巡逻|放哨|守营|留守|看守|守夜|巡逻/;

/** 不属于生产/学习/研发/建造队列的营地勤务（巡逻、放哨等） */
export function should_not_be_in_work_queue(workName: string): boolean {
  if (NON_WORK_QUEUE_NAME_RE.test(workName)) {
    return true;
  }
  if (/巡逻|警戒|看守|守营|留守/.test(workName) && !CATALOG_NAMES.has(workName)) {
    return true;
  }
  return false;
}

function affairNameFromTask(task: string): string {
  if (/营地巡逻|巡逻/.test(task)) return '营地巡逻';
  if (/放哨|守夜/.test(task)) return '营地放哨';
  if (/守营|留守|看守/.test(task)) return '营地值守';
  return task;
}

/** 将误写入工作队列的巡逻/勤务项迁移至综合事物 */
export function migrate_misplaced_work_queue_items(stat: Stat): boolean {
  let changed = false;
  for (const name of Object.keys(stat.工作队列)) {
    if (!should_not_be_in_work_queue(name)) continue;
    const work = stat.工作队列[name];
    const existing = stat.综合事物[name];
    if (!existing) {
      stat.综合事物[name] = {
        说明: work.状态 === '进行中' ? `正在进行：${name}` : `待安排：${name}`,
        状态: work.状态 === '进行中' ? '进行中' : '待定',
        具名参与: [...work.具名指派],
        来源: '由工作队列校正',
        创建日期: stat.世界.兽历,
        元数据: {},
      };
    } else {
      existing.具名参与 = _.uniq([...existing.具名参与, ...work.具名指派]);
      if (work.状态 === '进行中') {
        existing.状态 = '进行中';
      }
    }
    delete stat.工作队列[name];
    changed = true;
    console.info('[综合事物] 已从工作队列迁出:', name);
  }
  return changed;
}

function npc_has_patrol_task(task: string): boolean {
  const t = task.trim();
  if (!t || /外出|狩猎|采集|探索|带领/.test(t)) {
    return false;
  }
  return PATROL_TASK_RE.test(t);
}

/** 无 NPC 仍承担对应勤务时，将过期的综合事务标记为已完成 */
export function reconcile_stale_comprehensive_affairs(stat: Stat): boolean {
  let changed = false;
  for (const [name, affair] of Object.entries(stat.综合事物)) {
    if (affair.状态 !== '进行中') {
      continue;
    }
    if (name.startsWith('归来清点') || affair.来源 === '时间结算') {
      continue;
    }
    if (PATROL_TASK_RE.test(name) || /值守|留守|巡逻|放哨/.test(name)) {
      const stillActive = affair.具名参与.some(npcName => {
        const task = stat.具名NPC[npcName]?.当前任务 ?? '';
        return npc_has_patrol_task(task);
      });
      if (!stillActive) {
        affair.状态 = '已完成';
        changed = true;
        console.info('[综合事物] 勤务已结束，标记完成:', name);
      }
      continue;
    }
    if (affair.具名参与.length === 0) {
      continue;
    }
    const keywords = story_affair_keywords(name, affair.说明);
    const stillActive = affair.具名参与.some(npcName => {
      const npc = stat.具名NPC[npcName];
      return npc && npc_still_on_story_affair(npc, keywords);
    });
    if (!stillActive) {
      affair.状态 = '已完成';
      changed = true;
      console.info('[综合事物] 剧情事务已无相关任务，标记完成:', name);
    }
  }
  return changed;
}

function story_affair_keywords(name: string, description: string): string[] {
  const blob = `${name}${description}`;
  const keys = new Set<string>();
  if (name.length >= 3) {
    keys.add(name);
  }
  if (/迫降|破降|铁壳|坠星舱/.test(blob)) {
    keys.add('迫降舱', '破降舱', '铁壳', '迫降', '破降');
  }
  if (/防御|防风|木桩|工事/.test(blob)) {
    keys.add('防御', '修缮', '防风', '木桩', '工事');
  }
  for (const part of name.match(/[\u4e00-\u9fff]{2,}/g) ?? []) {
    if (part.length >= 2 && !/进行|营地|探索/.test(part)) {
      keys.add(part);
    }
  }
  return [...keys];
}

function npc_still_on_story_affair(npc: Stat['具名NPC'][string], keywords: string[]): boolean {
  const blob = `${npc.当前任务 ?? ''}${npc.当前位置 ?? ''}`;
  return keywords.some(kw => kw.length >= 2 && blob.includes(kw));
}

/** 据具名 NPC 当前任务补写尚未分类的营地勤务 */
export function sync_comprehensive_affairs_from_npc_tasks(stat: Stat): boolean {
  let changed = false;
  for (const [name, npc] of Object.entries(stat.具名NPC)) {
    const task = (npc.当前任务 ?? '').trim();
    if (!task || !PATROL_TASK_RE.test(task)) continue;
    if (/外出|狩猎|采集|探索|带领/.test(task)) continue;

    const affairName = affairNameFromTask(task);
    const existing = stat.综合事物[affairName];
    if (!existing) {
      stat.综合事物[affairName] = {
        说明: `执行${task}，维持营地安全与秩序。`,
        状态: '进行中',
        具名参与: [name],
        来源: '剧情',
        创建日期: stat.世界.兽历,
        元数据: {},
      };
      changed = true;
      console.info('[综合事物] 从 NPC 任务写入:', affairName, name);
      continue;
    }
    if (!existing.具名参与.includes(name)) {
      existing.具名参与 = _.uniq([...existing.具名参与, name]);
      existing.状态 = '进行中';
      changed = true;
    }
  }
  return changed;
}

export function sync_comprehensive_affairs(stat: Stat): boolean {
  return (
    migrate_misplaced_work_queue_items(stat) ||
    reconcile_stale_comprehensive_affairs(stat) ||
    sync_comprehensive_affairs_from_npc_tasks(stat)
  );
}
