import { isStatusBarLocalMutation } from '@util/common';
import { get_disbanded_squad_names } from '@/兽耳娘/util/squadUserCommands';
import { klona } from 'klona';
/** pull 时保留本地已有、远端尚未写入的键（如 UI 刚新建的编队/队列项） */
function merge_local_only_record_keys(local, remote, key) {
    const local_record = local[key];
    const remote_record = remote[key];
    if (!local_record || typeof local_record !== 'object' || Array.isArray(local_record)) {
        return remote;
    }
    if (!remote_record || typeof remote_record !== 'object' || Array.isArray(remote_record)) {
        return { ...local, [key]: klona(local_record) };
    }
    const local_obj = local_record;
    const remote_obj = remote_record;
    const local_only = _.pickBy(local_obj, (_, name) => !(name in remote_obj));
    if (_.isEmpty(local_only)) {
        return remote;
    }
    return {
        ...remote,
        [key]: { ...remote_obj, ...local_only },
    };
}
function merge_pulled_stat_data(local, remote) {
    let merged = klona(remote);
    const disbanded = get_disbanded_squad_names();
    if (disbanded.size > 0) {
        const squads = merged.探索编队;
        if (squads && typeof squads === 'object') {
            for (const name of disbanded) {
                delete squads[name];
            }
        }
    }
    for (const key of ['工作队列']) {
        merged = merge_local_only_record_keys(local, merged, key);
    }
    // 探索编队：pull 时不合并「仅本地有、远端无」的项，避免重 roll 后旧编队被 resurrect
    if (isStatusBarLocalMutation()) {
        merged = merge_local_only_record_keys(local, merged, '探索编队');
    }
    return merged;
}
function pull_stat_data(schema, variable_option, data, ignoreUpdates) {
    const stat_data = _.get(getVariables(variable_option), 'stat_data', {});
    const result = schema.safeParse(stat_data);
    if (result.error) {
        return;
    }
    const merged = merge_pulled_stat_data(data.value, result.data);
    if (!_.isEqual(data.value, merged)) {
        ignoreUpdates(() => {
            data.value = merged;
        });
    }
}
export function defineMvuDataStore(schema, variable_option, additional_setup) {
    if (variable_option.type === 'message' &&
        (variable_option.message_id === undefined || variable_option.message_id === 'latest')) {
        variable_option.message_id = -1;
    }
    return defineStore(`mvu_data.${_(variable_option)
        .entries()
        .sortBy(entry => entry[0])
        .map(entry => entry[1])
        .join('.')}`, errorCatched(() => {
        const stat_data = _.get(getVariables(variable_option), 'stat_data', {});
        const parsed = schema.safeParse(stat_data, { reportInput: true });
        if (!parsed.success) {
            console.error('[MVU store] stat_data 校验失败，将尝试用 schema 默认值恢复', parsed.error);
        }
        const data = ref((parsed.success ? parsed.data : schema.parse({}, { reportInput: true })));
        const { ignoreUpdates } = watchIgnorable(data, new_data => {
            const result = schema.safeParse(new_data);
            if (result.error) {
                return;
            }
            if (!_.isEqual(new_data, result.data)) {
                ignoreUpdates(() => {
                    data.value = result.data;
                });
            }
            updateVariablesWith(variables => _.set(variables, 'stat_data', result.data), variable_option);
        }, { deep: true });
        const pull = () => {
            if (isStatusBarLocalMutation()) {
                return;
            }
            pull_stat_data(schema, variable_option, data, ignoreUpdates);
        };
        if (additional_setup) {
            additional_setup(data);
        }
        useIntervalFn(pull, 2000);
        if (typeof eventOn === 'function') {
            eventOn(tavern_events.GENERATION_ENDED, pull);
            eventOn(tavern_events.MESSAGE_UPDATED, pull);
            if (typeof Mvu !== 'undefined') {
                eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, pull);
            }
        }
        return { data };
    }));
}
