import type { Schema } from '../../../schema';
import {
  default_warehouse_cap,
  normalize_warehouse_item_name,
} from '../../../constants/warehouseCatalog';

type SettlementKind = '探索' | '狩猎' | '采集' | '工作';

export type ParsedSettlementCard = {
  kind: SettlementKind;
  target: string;
  materials: Array<{ name: string; amount: number }>;
};

const WAREHOUSE_RESOURCE_ALIAS: Record<string, string> = {
  生藤蔓: '藤蔓',
  完整大兽皮: '完整小兽皮',
};

const SETTLEMENT_CARD_RE =
  /(?:<|&lt;)settlement_card(?:>|&gt;)([\s\S]*?)(?:<|&lt;)\/settlement_card(?:>|&gt;)/gi;

const SETTLEMENT_FIELD_RE =
  /\[(类型|品质|标题|副标题|参与|参与人员|说明|结算对象|获取物资|消耗状况|事件描述|消耗|产出|状态|情报带回|时间消耗|队伍状态|[^\]|]+)\|([^\]]*)\]/g;

const RESERVED_FIELDS = new Set([
  '类型',
  '品质',
  '标题',
  '副标题',
  '参与',
  '参与人员',
  '说明',
  '结算对象',
  '结算事项',
  '获取物资',
  '消耗状况',
  '事件描述',
  '消耗',
  '产出',
  '状态',
  '情报带回',
  '时间消耗',
  '队伍状态',
  '编队',
]);

const HUNT_RESOURCE_RE = /生肉|兽皮|兽脂|骨骼|皮革|猎物|内脏|狼/;
const GATHER_RESOURCE_RE = /块茎|野果|藤蔓|木柴|菌菇|浆果|植物|果|藤/;

function normalizeResourceName(name: string): string {
  return WAREHOUSE_RESOURCE_ALIAS[name.trim()] ?? name.trim();
}

function expandCompoundResourceName(name: string): string[] {
  if (name.includes('/')) {
    return name.split('/').map(part => normalizeResourceName(part)).filter(Boolean);
  }
  return [normalizeResourceName(name)];
}

function parseOutputStarMaterials(raw: string): Array<{ name: string; amount: number }> {
  const items: Array<{ name: string; amount: number }> = [];
  for (const part of raw.split(/[,，、]/)) {
    const trimmed = part.trim();
    if (!trimmed) continue;
    let m = trimmed.match(/^(.+?)[*×xX]\s*(\d+)\s*$/);
    if (!m) {
      m = trimmed.match(/^(.+?)[:：]\+?(\d+)\s*$/);
    }
    if (!m) continue;
    const amount = Number(m[2]);
    if (!Number.isFinite(amount) || amount <= 0) continue;
    const names = expandCompoundResourceName(m[1]);
    if (names.length > 1) {
      let rest = amount;
      const base = Math.floor(amount / names.length);
      names.forEach((name, index) => {
        const add = index === names.length - 1 ? rest : base;
        items.push({ name, amount: add });
        rest -= add;
      });
    } else {
      items.push({ name: names[0], amount });
    }
  }
  return items;
}

function parseMaterialList(raw: string): Array<{ name: string; amount: number }> {
  return parseOutputStarMaterials(raw.replace(/\//g, ','));
}

function parseMarkdownMaterials(raw: string): Array<{ name: string; amount: number }> {
  const items: Array<{ name: string; amount: number }> = [];
  for (const line of raw.split('\n')) {
    const m = line.trim().match(/^[-•*]?\s*\[([^\]]+)\]\s*[x×*]\s*(\d+)/i);
    if (!m) continue;
    const amount = Number(m[2]);
    if (!Number.isFinite(amount) || amount <= 0) continue;
    const names = expandCompoundResourceName(m[1]);
    if (names.length > 1) {
      let rest = amount;
      const base = Math.floor(amount / names.length);
      names.forEach((name, index) => {
        const add = index === names.length - 1 ? rest : base;
        items.push({ name, amount: add });
        rest -= add;
      });
    } else {
      items.push({ name: names[0], amount });
    }
  }
  return items;
}

function extractMultilineField(content: string, fieldName: string): string {
  const marker = `[${fieldName}|`;
  const start = content.indexOf(marker);
  if (start < 0) return '';
  const bodyStart = start + marker.length;
  const lineEnd = content.indexOf('\n]', bodyStart);
  if (lineEnd >= 0) {
    return content.slice(bodyStart, lineEnd).trim();
  }
  const inlineEnd = content.indexOf(']', bodyStart);
  if (inlineEnd >= 0) {
    return content.slice(bodyStart, inlineEnd).trim();
  }
  return content.slice(bodyStart).trim();
}

function inferKindFromSquadName(name: string): SettlementKind {
  if (/采集/.test(name)) return '采集';
  if (/狩猎/.test(name)) return '狩猎';
  if (/巡逻|探索/.test(name)) return '探索';
  if (/工作|交付|队列/.test(name)) return '工作';
  return '探索';
}

function inferKindFromTitle(title: string, content: string): SettlementKind {
  if (/^类型\|(探索|狩猎|采集|工作)/.test(content)) {
    const m = content.match(/\[类型\|(探索|狩猎|采集|工作)\]/);
    if (m) return m[1] as SettlementKind;
  }
  if (/采集/.test(title) && !/狩猎/.test(title)) return '采集';
  if (/狩猎/.test(title) && !/采集/.test(title)) return '狩猎';
  if (/工作|交付/.test(title)) return '工作';
  return '探索';
}

function parseSquadNamedSettlementLines(content: string): ParsedSettlementCard[] {
  const cards: ParsedSettlementCard[] = [];
  const lineRe = /\[(采集队|狩猎队|巡逻队|探索队)(?:_[^|\]]+|\/[^|\]]+)?\|(.+?)(?:\|([^\]]+))?\]/g;
  let m: RegExpExecArray | null;
  while ((m = lineRe.exec(content)) !== null) {
    const squadKey = m[0].slice(1, m[0].indexOf('|'));
    const materials = parseOutputStarMaterials(m[2]);
    if (materials.length === 0) continue;
    cards.push({
      kind: inferKindFromSquadName(squadKey),
      target: squadKey,
      materials,
    });
  }
  return cards;
}

function parseMultiSquadBlocks(content: string): ParsedSettlementCard[] {
  return content
    .split(/(?=\[编队\|)/)
    .map(chunk => {
      if (!/\[编队\|/.test(chunk)) return null;
      const squad = chunk.match(/\[编队\|([^\]]+)\]/)?.[1]?.trim();
      if (!squad) return null;
      const output = chunk.match(/\[产出\|([^\]]+)\]/)?.[1] ?? '';
      return {
        kind: inferKindFromSquadName(squad),
        target: squad,
        materials: parseOutputStarMaterials(output),
      };
    })
    .filter((card): card is ParsedSettlementCard => card !== null && card.materials.length > 0);
}

function parseCombinedMaterialBlock(content: string): ParsedSettlementCard[] {
  const matBlock = extractMultilineField(content, '物资获取');
  if (!matBlock) return [];
  const titleMatch = content.match(/^\[([^\]|]+)\|([^\]]+)\]/);
  const title = titleMatch?.[2]?.trim() ?? '归来清点';
  const materials = parseMarkdownMaterials(matBlock);
  if (materials.length === 0) return [];

  if (/狩猎/.test(title) && /采集/.test(title)) {
    const hunt = materials.filter(m => HUNT_RESOURCE_RE.test(m.name));
    const gather = materials.filter(m => GATHER_RESOURCE_RE.test(m.name));
    const other = materials.filter(m => !HUNT_RESOURCE_RE.test(m.name) && !GATHER_RESOURCE_RE.test(m.name));
    const cards: ParsedSettlementCard[] = [];
    if (hunt.length) {
      cards.push({ kind: '狩猎', target: `${title}·狩猎`, materials: hunt });
    }
    if (gather.length || other.length) {
      cards.push({ kind: '采集', target: `${title}·采集`, materials: [...gather, ...other] });
    }
    return cards.length ? cards : [{ kind: inferKindFromTitle(title, content), target: title, materials }];
  }

  return [{ kind: inferKindFromTitle(title, content), target: title, materials }];
}

export function parseSettlementCardContent(content: string): ParsedSettlementCard {
  const fields: Record<string, string> = {};
  const rewardLines: Array<{ name: string; amount: number }> = [];

  let m: RegExpExecArray | null;
  SETTLEMENT_FIELD_RE.lastIndex = 0;
  while ((m = SETTLEMENT_FIELD_RE.exec(content)) !== null) {
    const key = m[1].trim();
    const val = m[2].trim();
    if (key === '编队' || key === '物资获取') continue;
    fields[key] = val;
    if (RESERVED_FIELDS.has(key) || !val) continue;
    const amountMatch = val.match(/^\+?(\d+)\s*$/);
    if (amountMatch) {
      rewardLines.push({
        name: normalizeResourceName(key),
        amount: Number(amountMatch[1]),
      });
    }
  }

  if (fields['产出']) {
    return {
      kind: inferKindFromSquadName(fields['编队'] ?? fields['结算对象'] ?? ''),
      target: fields['编队'] ?? fields['结算对象'] ?? '',
      materials: parseOutputStarMaterials(fields['产出']),
    };
  }

  const materials = fields['获取物资']
    ? parseMaterialList(fields['获取物资'])
    : rewardLines;

  const kindSource = fields['结算对象'] ?? fields['编队'] ?? fields['标题'] ?? '';
  return {
    kind: fields['类型']
      ? (fields['类型'] as SettlementKind)
      : inferKindFromSquadName(kindSource) || inferKindFromTitle(kindSource, content),
    target: fields['结算对象'] ?? fields['标题'] ?? fields['编队'] ?? '',
    materials,
  };
}

function parseSettlementCardBlocks(content: string): ParsedSettlementCard[] {
  const squadNamed = parseSquadNamedSettlementLines(content);
  if (squadNamed.length) return squadNamed;
  if (/\[编队\|/.test(content)) {
    const multi = parseMultiSquadBlocks(content);
    if (multi.length) return multi;
  }
  const combined = parseCombinedMaterialBlock(content);
  if (combined.length) return combined;
  const single = parseSettlementCardContent(content);
  return single.materials.length ? [single] : [single];
}

export function extractSettlementCardsFromStory(story: string): ParsedSettlementCard[] {
  if (!story) return [];
  const cards: ParsedSettlementCard[] = [];
  SETTLEMENT_CARD_RE.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = SETTLEMENT_CARD_RE.exec(story)) !== null) {
    cards.push(...parseSettlementCardBlocks(match[1]));
  }
  return cards;
}

function warehouseReflectsCards(stat: Schema, cards: ParsedSettlementCard[]): boolean {
  if (cards.length === 0) return false;
  return cards.every(card =>
    card.materials.every(m => (stat.营地.仓库储备[m.name]?.当前 ?? 0) >= m.amount),
  );
}

function affairForCard(stat: Schema, card: ParsedSettlementCard): string | undefined {
  return Object.keys(stat.综合事物).find(name => {
    if (!/^归来清点·|^交付清点·/.test(name)) return false;
    const suffix = name.replace(/^归来清点·|^交付清点·/, '');
    const targetNorm = card.target.replace(/_/g, '').replace(/\//g, '');
    if (suffix && targetNorm.includes(suffix.replace(/队/g, ''))) return true;
    if (targetNorm.includes(suffix.replace(/[-_·]/g, ''))) return true;
    if (card.target && name.includes(card.target.split(/[-_·/]/)[0])) return true;
    if (card.kind === '采集' && name.includes('采集')) return true;
    if (card.kind === '狩猎' && name.includes('狩猎')) return true;
    if (card.kind === '工作' && name.includes('交付')) return true;
    return false;
  });
}

function addToWarehouse(stat: Schema, name: string, amount: number): void {
  const key = normalize_warehouse_item_name(name);
  const slot = stat.营地.仓库储备[key] ?? stat.营地.仓库储备[name] ?? {
    当前: 0,
    上限: default_warehouse_cap(key),
  };
  slot.当前 = Math.min(slot.上限, slot.当前 + amount);
  stat.营地.仓库储备[key] = slot;
  if (key !== name && stat.营地.仓库储备[name]) {
    delete stat.营地.仓库储备[name];
  }
}

/** 将各资源「当前」限制在「上限」内，修复超仓与脚本重复入库 */
export function clampWarehouseReserves(stat: Schema): boolean {
  let changed = false;
  for (const slot of Object.values(stat.营地.仓库储备)) {
    if (slot.当前 > slot.上限) {
      slot.当前 = slot.上限;
      changed = true;
    }
    if (slot.当前 < 0) {
      slot.当前 = 0;
      changed = true;
    }
  }
  return changed;
}

/**
 * JSONPatch 未写入或写错仓库时，按 settlement_card 明文补入库（不自行推算产出）。
 */
export function syncWarehouseFromSettlementStory(
  stat: Schema,
  story: string,
  options: { messageText?: string; messageId?: number; syncedFloors?: number[] } = {},
): boolean {
  if (!story) return false;
  if (
    options.messageId !== undefined &&
    options.syncedFloors?.includes(options.messageId)
  ) {
    // 仍允许补全「归来清点」状态，仅跳过重复入库
  }

  const cards = extractSettlementCardsFromStory(story);
  if (cards.length === 0) return false;

  const alreadySynced =
    options.messageId !== undefined &&
    options.syncedFloors?.includes(options.messageId);

  let changed = false;
  for (const card of cards) {
    const affairName = affairForCard(stat, card);
    if (affairName && stat.综合事物[affairName]?.状态 !== '已完成') {
      stat.综合事物[affairName].状态 = '已完成';
      changed = true;
    }
  }

  if (alreadySynced) {
    return changed || clampWarehouseReserves(stat);
  }

  if (alreadySynced) {
    return changed || clampWarehouseReserves(stat);
  }

  // 变量已反映卡片增量时才跳过；AI 写了 patch 路径但 op 失败时仍按 settlement_card 补写
  if (warehouseReflectsCards(stat, cards)) {
    return changed || clampWarehouseReserves(stat);
  }

  for (const card of cards) {
    if (card.materials.length === 0) continue;
    const affairName = affairForCard(stat, card);
    if (affairName && stat.综合事物[affairName]?.状态 === '已完成') {
      continue;
    }

    for (const { name, amount } of card.materials) {
      addToWarehouse(stat, name, amount);
      changed = true;
    }
  }

  if (changed) {
    console.info('[仓库] 已从 settlement_card 补写入库（JSONPatch 遗漏或路径无效）');
  }
  return changed || clampWarehouseReserves(stat);
}

/** AI 误写 /仓库储备 时合并到 /营地/仓库储备（仅路径修正，不自行结算产出） */
export function repairMisplacedWarehouse(data: Schema): boolean {
  const root = data as Schema & { 仓库储备?: Schema['营地']['仓库储备'] };
  const misplaced = root.仓库储备;
  if (!misplaced || typeof misplaced !== 'object') return false;

  let changed = false;
  for (const [name, entry] of Object.entries(misplaced)) {
    if (!entry || typeof entry !== 'object') continue;
    const current = Number(entry.当前);
    const max = Number(entry.上限);
    const slot = data.营地.仓库储备[name] ?? { 当前: 0, 上限: 200 };
    if (Number.isFinite(current) && current > slot.当前) {
      slot.当前 = current;
      changed = true;
    }
    if (Number.isFinite(max) && max > slot.上限) {
      slot.上限 = max;
      changed = true;
    }
    data.营地.仓库储备[name] = slot;
  }
  delete root.仓库储备;
  if (changed) {
    console.info('[仓库] 已合并误路径 /仓库储备 → /营地/仓库储备');
  }
  return changed || clampWarehouseReserves(data);
}

export function extractStoryFromMessage(text: string): string {
  const m = text.match(/(?:<|&lt;)story(?:>|&gt;)([\s\S]*?)(?:<|&lt;)\/story(?:>|&gt;)/i);
  return m?.[1] ?? text;
}

export function getLatestAssistantStoryAndMessage(): {
  story: string;
  message: string;
  messageId?: number;
} {
  if (typeof getChatMessages !== 'function') {
    return { story: '', message: '' };
  }
  const latest = getChatMessages(-1, { role: 'assistant' })[0];
  if (!latest) {
    return { story: '', message: '' };
  }
  return {
    story: extractStoryFromMessage(latest.message),
    message: latest.message,
    messageId: latest.message_id,
  };
}
