import type { Schema } from '../schema';

const USER_INPUT_RE = /<本轮用户输入>([\s\S]*?)<\/本轮用户输入>/i;

const STORE_KEYWORD_RE =
  /(?:放进|存入|存进|放入|搬进|纳入|登记|储存).{0,16}(?:仓库|储物|储备)|(?:仓库|储物仓|部落内部储物).{0,12}(?:存放|储备|入库)|入库/;

const VAGUE_DEPOSIT_SEGMENT =
  /^(?:[""「]?[把将])?(?:剩下的|剩余的|余下的|所有|这些|那些|全部)?(?:的)?(?:食物|物资|东西|物品|货物|储备)(?:之类|什么的)?[""」]?$/;

const INVALID_ITEM_NAME_RE =
  /^(?:[""「『]|把|将|把|剩下|剩余|所有|这些|那些|放进|存入|存进|放入|搬进|纳入|登记|仓库|储物|食物|物资|东西|物品|货物|箱|个|份|块|颗|枚|把|捆|袋|斤|只|头|条|一些|部分|全部)/;

const TIME_OR_COUNT_NOISE =
  /^(小时|分钟|天|日|人|名|族|位|只|次|回|层|楼|岁|年|月|周|队|箱|个|份|块|颗|枚|把|捆|袋|斤|头|条|一些|部分|全部|剩余|食物|物资|东西|物品|货物)$/;

function extractUserInputs(): string[] {
  if (typeof getChatMessages !== 'function') {
    return [];
  }
  return getChatMessages('0-{{lastMessageId}}')
    .filter(m => m.role === 'user')
    .flatMap(m => {
      const hit = USER_INPUT_RE.exec(m.message);
      USER_INPUT_RE.lastIndex = 0;
      return hit?.[1] ? [hit[1].trim()] : [];
    });
}

function ensureWarehouseSlot(stat: Schema, name: string) {
  const key = normalize_warehouse_item_name(name);
  const slot = stat.营地.仓库储备[key] ?? { 当前: 0, 上限: default_warehouse_cap(key) };
  stat.营地.仓库储备[key] = slot;
  return slot;
}

function cleanItemName(raw: string): string {
  return raw
    .trim()
    .replace(/^[""「『]+|[""」』]+$/g, '')
    .replace(/^(?:把|将|把|的|等|和|与|及|以及|还有|各种|大量|少量|若干|剩下|剩余)/, '')
    .replace(/^箱/, '')
    .replace(/(?:等|之类|什么的|什么的)$/g, '')
    .trim();
}

function isValidItemName(name: string): boolean {
  if (!name || name.length < 2 || name.length > 16) {
    return false;
  }
  if (TIME_OR_COUNT_NOISE.test(name)) {
    return false;
  }
  if (INVALID_ITEM_NAME_RE.test(name)) {
    return false;
  }
  if (/^\d+$/.test(name)) {
    return false;
  }
  if (/[放进存入仓库储物储备]/.test(name)) {
    return false;
  }
  return true;
}

type ParsedItem = { name: string; amount: number };

/** 清除误解析写入仓库的条目（如「把剩下的食物」「箱罐头」） */
export function purge_invalid_warehouse_entries(stat: Schema): boolean {
  let changed = false;
  for (const name of Object.keys(stat.营地.仓库储备)) {
    const cleaned = cleanItemName(name);
    if (
      name !== cleaned ||
      !isValidItemName(cleaned) ||
      VAGUE_DEPOSIT_SEGMENT.test(name) ||
      /^箱/.test(name)
    ) {
      delete stat.营地.仓库储备[name];
      changed = true;
      console.info('[仓库] 已移除误解析条目:', name);
      continue;
    }
    if (name.startsWith('箱') && isValidItemName(cleaned)) {
      const slot = stat.营地.仓库储备[name];
      const target = stat.营地.仓库储备[cleaned] ?? { 当前: 0, 上限: 200 };
      target.当前 = Math.max(target.当前, slot.当前);
      stat.营地.仓库储备[cleaned] = target;
      delete stat.营地.仓库储备[name];
      changed = true;
    }
  }
  return changed;
}

function parseDepositClauseItems(text: string): ParsedItem[] {
  const items: ParsedItem[] = [];
  const clause = text.match(
    /(?:^|[""「])?(?:把|将)?(.+?)(?:放进|存入|存进|放入|搬进|纳入|登记到?).{0,14}(?:仓库|储物仓|储物|储备)/,
  );
  if (!clause?.[1]) {
    return items;
  }
  let segment = clause[1]
    .replace(/^[""「『]+|[""」』]+$/g, '')
    .replace(/^(?:把|将)/, '')
    .trim();
  if (VAGUE_DEPOSIT_SEGMENT.test(segment)) {
    return items;
  }
  segment = segment.replace(/^(?:剩下的|剩余|所有|这些|那些)/, '').trim();
  if (!segment || VAGUE_DEPOSIT_SEGMENT.test(segment)) {
    return items;
  }
  for (const part of segment.split(/[、，,和及与]/)) {
    const trimmed = cleanItemName(part);
    if (isValidItemName(trimmed)) {
      items.push({ name: trimmed, amount: 1 });
    }
  }
  return items;
}

function parseItemsFromText(text: string, perBoxHint: number): ParsedItem[] {
  const items: Map<string, number> = new Map();
  let perBox = perBoxHint;

  const perBoxMatch = text.match(/每箱\s*(\d+)/);
  if (perBoxMatch) {
    perBox = Number(perBoxMatch[1]);
  }

  const add = (name: string, amount: number) => {
    const cleaned = cleanItemName(name);
    if (!isValidItemName(cleaned) || !Number.isFinite(amount) || amount <= 0) {
      return;
    }
    items.set(cleaned, Math.max(items.get(cleaned) ?? 0, amount));
  };

  for (const { name, amount } of parseDepositClauseItems(text)) {
    add(name, amount);
  }

  for (const m of text.matchAll(/(\d+)\s*箱\s*(?:肉类)?([^\d\s，,。；\n和及]+)/g)) {
    const boxes = Number(m[1]);
    const unit = perBox > 0 ? boxes * perBox : boxes;
    add(m[2], unit);
  }

  for (const m of text.matchAll(
    /(\d+)\s*(个|份|块|颗|枚|把|捆|袋|斤|只|头|条)\s*([一-龥A-Za-z·]{2,12})/g,
  )) {
    add(m[3], Number(m[1]));
  }

  for (const m of text.matchAll(/([一-龥A-Za-z·]{2,12})\s*[×x*]\s*(\d+)/g)) {
    add(m[1], Number(m[2]));
  }

  for (const m of text.matchAll(/\[([^\]|]+)\|\+?(\d+)\s*\]/g)) {
    add(m[1], Number(m[2]));
  }

  return [...items.entries()].map(([name, amount]) => ({ name, amount }));
}

function resolvePerBoxHint(inputs: string[]): number {
  for (const text of inputs) {
    const m = text.match(/每箱\s*(\d+)/);
    if (m) {
      return Number(m[1]);
    }
  }
  return 0;
}

/**
 * 用户输入含入库/仓库类关键词时，从对话中解析物资名与数量并补写入库（AI 未 JSONPatch 时）。
 */
export function sync_user_warehouse_deposits(stat: Schema): boolean {
  const inputs = extractUserInputs();
  if (inputs.length === 0) {
    return false;
  }

  let changed = purge_invalid_warehouse_entries(stat);

  const storeRequested = inputs.some(t => STORE_KEYWORD_RE.test(t));
  if (!storeRequested) {
    return changed;
  }

  const consumed = inputs.some(t => /煮|分发|分给|吃饱|开.*罐头|当场吃|分食/.test(t));
  const ratio = consumed ? 0.65 : 1;
  const perBoxHint = resolvePerBoxHint(inputs);

  const merged = new Map<string, number>();
  for (const text of inputs) {
    for (const { name, amount } of parseItemsFromText(text, perBoxHint)) {
      merged.set(name, Math.max(merged.get(name) ?? 0, amount));
    }
  }

  if (merged.size === 0) {
    return changed;
  }

  for (const [name, amount] of merged) {
    const target = Math.max(1, Math.floor(amount * ratio));
    const slot = ensureWarehouseSlot(stat, name);
    if (slot.当前 < target) {
      slot.当前 = target;
      changed = true;
    }
  }

  if (changed) {
    console.info('[仓库] 已从用户入库描述补写:', [...merged.keys()].join('、'));
  }
  return changed;
}
