import type { Schema } from '../../../schema';
import { migrate_exploration_areas } from '../../../util/explorationAreaMigration';

type ExplorationArea = Schema['探索区域'][string];
export type AreaDistance = ExplorationArea['距离'];

export const EXPLORATION_AREA_DEFAULTS: Record<string, ExplorationArea> = {
  湖畔营地: {
    描述: '坠星盆地边缘的流浪猫耳部族临时营地，简易火塘常熄灭，食水紧缺。',
    路程: '0小时',
    危险度: '低',
    已掌握: true,
    探索度: 70,
    距离: '近',
  },
  飞船残骸周边: {
    描述: '熟悉的营地区域，可采集枯枝与残骸金属碎片。',
    路程: '0小时',
    危险度: '极低',
    已掌握: true,
    探索度: 100,
    距离: '近',
  },
  中央大陆林缘: {
    描述: '林缘地带，可能找到食草野兽与可食用浆果，偶有狼群出没。',
    路程: '半个日落',
    危险度: '低',
    已掌握: false,
    探索度: 30,
    距离: '中',
  },
  坠星盆地外围: {
    描述: '营地视线之外的乱石与矮林，资源更丰富，但夜行兽与狼群活动频繁。',
    路程: '一个日落',
    危险度: '中',
    已掌握: false,
    探索度: 10,
    距离: '远',
  },
};

export const AREA_DISTANCE_ORDER: AreaDistance[] = ['近', '中', '远'];

export function infer_area_distance(area: Partial<ExplorationArea>): AreaDistance {
  if (area.距离 === '近' || area.距离 === '中' || area.距离 === '远') {
    return area.距离;
  }
  const route = area.路程 ?? '';
  if (/即刻|0小时|营内|营地|当前/.test(route)) {
    return '近';
  }
  if (/半个|半日|较短|两三个小时|数小时/.test(route)) {
    return '中';
  }
  return '远';
}

/** 补全缺失的近/中/远探索区域，并为旧存档推断距离档位 */
export function ensure_exploration_area_catalog(stat: Schema): boolean {
  let changed = migrate_exploration_areas(stat.探索区域 as Record<string, unknown>);

  for (const [name, defaults] of Object.entries(EXPLORATION_AREA_DEFAULTS)) {
    if (!stat.探索区域[name]) {
      stat.探索区域[name] = { ...defaults };
      changed = true;
      console.info('[探索区域] 已补全默认区域:', name);
    }
  }

  for (const area of _.values(stat.探索区域)) {
    const distance = infer_area_distance(area);
    if (area.距离 !== distance) {
      area.距离 = distance;
      changed = true;
    }
  }

  return changed;
}

export function group_areas_by_distance(
  areas: [string, ExplorationArea][],
): { distance: AreaDistance; items: [string, ExplorationArea][] }[] {
  const grouped = new Map<AreaDistance, [string, ExplorationArea][]>(
    AREA_DISTANCE_ORDER.map(distance => [distance, []]),
  );
  for (const entry of areas) {
    const distance = infer_area_distance(entry[1]);
    grouped.get(distance)?.push(entry);
  }
  return AREA_DISTANCE_ORDER.map(distance => ({
    distance,
    items: grouped.get(distance) ?? [],
  })).filter(section => section.items.length > 0);
}
