import type { Schema } from '../../../schema';

export type FuelMaterial = {
  id: string;
  label: string;
  fuelValue: number;
  hoursPerUnit: number;
};

/** 露天火塘每日约消耗 10 单位；石砌防风火塘约 4 单位 */
export const FUEL_MATERIALS: FuelMaterial[] = [
  { id: '普通木柴', label: '普通木柴', fuelValue: 1, hoursPerUnit: 2.4 },
  { id: '木炭', label: '木炭', fuelValue: 2, hoursPerUnit: 6 },
  { id: '坚固木材', label: '坚固木材（应急）', fuelValue: 0.8, hoursPerUnit: 1.8 },
  { id: '引火物', label: '引火物/干草', fuelValue: 0.3, hoursPerUnit: 0.6 },
];

export function hasWindproofFirepit(buildings: Schema['营地']['当前建筑']) {
  return Object.keys(buildings).some(
    name => name.includes('防风火塘') || (name.includes('石砌') && name.includes('火塘')),
  );
}

export function dailyFuelBurn(buildings: Schema['营地']['当前建筑']) {
  return hasWindproofFirepit(buildings) ? 4 : 10;
}

export function fuelHoursRemaining(fuelCurrent: number, dailyBurn: number) {
  if (fuelCurrent <= 0 || dailyBurn <= 0) return 0;
  return (fuelCurrent / dailyBurn) * 24;
}

export function formatFuelDuration(hours: number) {
  if (hours <= 0) return '已熄灭';
  if (hours < 1) return `约 ${Math.round(hours * 60)} 分钟`;
  const h = Math.floor(hours);
  const m = Math.round((hours - h) * 60);
  if (m === 0) return `约 ${h} 小时`;
  return `约 ${h} 小时 ${m} 分`;
}

export type FireIntensityLevel = '已熄灭' | '微弱' | '小火' | '中火' | '旺火';

/** 按燃料余量与火塘状态解析火势档位 */
export function resolveFireIntensity(
  fuelCurrent: number,
  fuelMax: number,
  dailyBurn: number,
  buildingState?: string,
): FireIntensityLevel {
  if (fuelCurrent <= 0) return '已熄灭';

  const fuelPercent = fuelMax > 0 ? (fuelCurrent / fuelMax) * 100 : 0;
  const hours = fuelHoursRemaining(fuelCurrent, dailyBurn);
  const state = String(buildingState ?? '');

  if (/稳定|旺/.test(state) || fuelPercent >= 70) return '旺火';
  if (/温火/.test(state) || (fuelPercent >= 30 && fuelPercent < 70)) return '中火';
  if (/微火/.test(state) || hours >= 2) return '小火';
  return '微弱';
}

/** 进度条：以「满一天（24h）续火」为 100% 显示剩余时间 */
export function fuelTimeBarPercent(fuelCurrent: number, dailyBurn: number) {
  if (fuelCurrent <= 0 || dailyBurn <= 0) return 0;
  const hours = fuelHoursRemaining(fuelCurrent, dailyBurn);
  return Math.min(100, Math.max(0, (hours / 24) * 100));
}

/** 部落篝火页右上角状态：有燃料即视为已点燃 */
export function formatFireDisplayLabel(fuelCurrent: number, dailyBurn: number): string {
  if (fuelCurrent <= 0) return '已熄灭';
  const duration = formatFuelDuration(fuelHoursRemaining(fuelCurrent, dailyBurn));
  return duration === '已熄灭' ? '已点燃' : `已点燃 · ${duration}`;
}

export const LEGACY_FIREPIT_KEY = '熄灭的火堆';
export const FIREPIT_KEY = '简易火塘';

/** 兼容旧存档键名「熄灭的火堆」，统一读写「简易火塘」 */
export function resolveFirepitKey(buildings: Schema['营地']['当前建筑']): string | null {
  if (buildings[FIREPIT_KEY]) return FIREPIT_KEY;
  if (buildings[LEGACY_FIREPIT_KEY]) return LEGACY_FIREPIT_KEY;
  return null;
}

export function migrateFirepitBuildingName(buildings: Schema['营地']['当前建筑']) {
  if (buildings[LEGACY_FIREPIT_KEY] && !buildings[FIREPIT_KEY]) {
    buildings[FIREPIT_KEY] = buildings[LEGACY_FIREPIT_KEY];
    delete buildings[LEGACY_FIREPIT_KEY];
  }
}

const COLD_STATE_RE = /冰冷|熄灭|死灰|无火|冷灰/;
const LIT_STATE_RE = /燃烧|温火|点燃|稳定|微火|旺/;

/** 有燃料即视为可燃烧；建筑状态「冰冷」在燃料>0 时视为未及时更新的陈旧值 */
export function isFireLit(fuelCurrent: number, buildingState: string | undefined): boolean {
  if (fuelCurrent <= 0) return false;
  const state = String(buildingState ?? '');
  if (LIT_STATE_RE.test(state)) return true;
  if (COLD_STATE_RE.test(state)) return true;
  return true;
}

/** 按燃料余量同步简易火塘的状态与描述，避免 UI 与变量脱节 */
export function syncFirepitWithFuel(
  buildings: Schema['营地']['当前建筑'],
  fuel: Schema['营地']['篝火燃料'],
) {
  migrateFirepitBuildingName(buildings);
  const pile = buildings[FIREPIT_KEY];
  if (!pile) return;

  const fuelCurrent = fuel.当前;
  const fuelPercent = fuel.上限 > 0 ? (fuelCurrent / fuel.上限) * 100 : 0;

  if (fuelCurrent <= 0) {
    pile.状态 = '冰冷';
    pile.描述 = '只剩下灰烬的火塘，急需重新生火';
    return;
  }

  if (fuelPercent >= 70) {
    pile.状态 = '稳定燃烧';
    pile.描述 = '火焰稳定，族人围着火塘说笑取暖';
  } else if (fuelPercent >= 30) {
    pile.状态 = '温火';
    pile.描述 = '火舌缩短，但尚可驱散寒意';
  } else {
    pile.状态 = '微火';
    pile.描述 = '火苗忽明忽暗，需要尽快添柴';
  }
}

export function fallbackTribeFireOpinion(
  fuelPercent: number,
  cohesion: number,
  warmth: number,
  fireLit: boolean,
): string {
  if (!fireLit || fuelPercent <= 0) {
    return '族人们围在冷灰旁低声抱怨，夜里没人敢睡踏实。';
  }
  if (fuelPercent >= 70) {
    return cohesion >= 50
      ? '火光映着兽耳，族人们围坐说笑，觉得首领把火塘照顾得很好。'
      : '火还算旺，但不少人仍担心明天还有没有柴烧。';
  }
  if (fuelPercent >= 30) {
    return warmth < 30
      ? '火舌变短了，挨饿受冻的族人开始埋怨后勤没跟上。'
      : '大家还能靠近取暖，可都在悄悄议论要不要省着添柴。';
  }
  return '火苗忽明忽暗，孩子们往大人怀里缩，族人们明显焦躁不安。';
}

/** @deprecated 使用 resolveTribeFireOpinion */
export const tribeFireOpinion = fallbackTribeFireOpinion;

/** 优先读 AI 写入的族众看法；无则用数值兜底（不从剧情片段推断，避免误抓单个 NPC 反应） */
export function resolveTribeFireOpinion(
  fuel: Schema['营地']['篝火燃料'],
  cohesion: number,
  warmth: number,
  fireLit: boolean,
): string {
  const custom = String(fuel.族众看法 ?? '').trim();
  if (custom) return custom;

  const fuelPercent = fuel.上限 > 0 ? (fuel.当前 / fuel.上限) * 100 : 0;
  return fallbackTribeFireOpinion(fuelPercent, cohesion, warmth, fireLit);
}

export function previewFuelAddition(material: FuelMaterial, amount: number, dailyBurn: number) {
  const addedFuel = material.fuelValue * amount;
  const addedHours = material.hoursPerUnit * amount;
  const equivalentDays = addedFuel / dailyBurn;
  return { addedFuel, addedHours, equivalentDays };
}

function extractStoryFromMessage(text: string): string {
  const m = text.match(/(?:<|&lt;)story(?:>|&gt;)([\s\S]*?)(?:<|&lt;)\/story(?:>|&gt;)/i);
  return m?.[1] ?? text;
}

function getLatestAssistantStoryText(): string {
  if (typeof getChatMessages !== 'function') {
    return '';
  }
  const msgs = getChatMessages('0-{{lastMessageId}}');
  const latestAssistant = [...msgs].reverse().find(m => m.role === 'assistant');
  if (!latestAssistant) {
    return '';
  }
  return extractStoryFromMessage(latestAssistant.message);
}

/** 剧情已描写生火成功，但 AI 未 update 篝火燃料时，补写初始燃料 */
const FIRE_LIT_STORY_RE =
  /将燃烧(?:的)?[^，。]{0,16}?(?:放|送|扔)?进(?:公共)?火塘|火焰(?:已经|在|逐渐|慢慢|越(?:来)?越).*?(?:窜|燃|变大|跳跃|腾起|跳动)|(?:橘|橙)红色(?:的)?(?:火苗|火焰)|噼里啪啦的燃烧|(?:公共)?火塘(?:里|中|的|边)?.*?(?:燃烧|燃起|点燃|有火|跳动的火|燃烧的(?:树枝|木柴|干草|草团))|(?:公共)?火塘.*?(?:重新|终于|已经|正在)(?:燃起|点燃|烧起来|燃烧)|(?:公共)?火塘.*?亮起来|(?:点燃|引燃).*?(?:公共)?火塘|(?:公共)?火塘.*?(?:旺火|温火|稳定(?:燃烧)?)/;

const FIRE_EXTINGUISHED_STORY_RE =
  /火塘.{0,32}(?:已|早已|彻底|完全|仍然|依然|还是)(?:熄灭|冷|灭|是冷的)|火塘里.{0,16}(?:只有|仅剩|尽是|全是).{0,12}(?:灰烬|冷灰|死灰)|火塘.{0,20}无火|公共火塘.{0,24}熄灭|火塘.{0,12}熄了/;

const NEGATIVE_FIRE_OPINION_RE = /熄灭|冷灰|无火|苦熬|只剩下灰|急需重新生火|围着冷灰|没人敢睡踏实/;

/** 族众看法已写火光/取暖等，但 AI 漏写 篝火燃料.当前 时视为已生火 */
function opinionConfirmsFireLit(opinion: string): boolean {
  const text = opinion.trim();
  if (!text || NEGATIVE_FIRE_OPINION_RE.test(text)) {
    return false;
  }
  return /(?:火光照|火光|火苗|火焰|燃烧|点燃|起火|暖意|温暖|橘红|橙红|驱散寒|续火)/.test(text);
}

function storyConfirmsFireExtinguished(story: string): boolean {
  const tail = story.slice(Math.floor(story.length * 0.55));
  return FIRE_EXTINGUISHED_STORY_RE.test(tail);
}

function storyConfirmsFireLit(story: string): boolean {
  if (!story) return false;
  if (FIRE_LIT_STORY_RE.test(story) && !storyConfirmsFireExtinguished(story)) {
    return true;
  }
  const latter = story.slice(Math.floor(story.length * 0.35));
  if (!/(?:公共)?火塘/.test(latter)) {
    return false;
  }
  if (!/(?:燃烧|燃起|点燃|有火|火苗|火焰|噼里啪啦|窜出|橘红|橙红|燃烧声)/.test(latter)) {
    return false;
  }
  return !storyConfirmsFireExtinguished(story);
}

function applyInferredCampfireFuel(
  buildings: Schema['营地']['当前建筑'],
  fuel: Schema['营地']['篝火燃料'],
  reason: string,
): boolean {
  fuel.当前 = Math.max(fuel.当前, 15);
  syncFirepitWithFuel(buildings, fuel);
  console.info(`[篝火燃料] ${reason}，补写初始燃料:`, fuel.当前);
  return true;
}

export function inferCampfireFuelFromStory(
  buildings: Schema['营地']['当前建筑'],
  fuel: Schema['营地']['篝火燃料'],
): boolean {
  if (fuel.当前 > 0) {
    return false;
  }
  const opinion = String(fuel.族众看法 ?? '');
  if (NEGATIVE_FIRE_OPINION_RE.test(opinion)) {
    return false;
  }
  migrateFirepitBuildingName(buildings);
  if (opinionConfirmsFireLit(opinion)) {
    return applyInferredCampfireFuel(buildings, fuel, '族众看法已反映生火');
  }
  const story = getLatestAssistantStoryText();
  if (storyConfirmsFireLit(story)) {
    return applyInferredCampfireFuel(buildings, fuel, '剧情已生火');
  }
  const pile = buildings[FIREPIT_KEY];
  if (pile) {
    const state = String(pile.状态 ?? '');
    const desc = String(pile.描述 ?? '');
    if (LIT_STATE_RE.test(state) || /燃烧|点燃|火焰|温火|旺火/.test(desc)) {
      return applyInferredCampfireFuel(buildings, fuel, '火塘状态已点燃');
    }
  }
  return false;
}
