/** MVU 变量键为「兽历」；界面展示时统一加「兽历」前缀 */
export function format_beast_calendar(raw: string | undefined): string {
  const text = String(raw ?? '').trim();
  if (!text) {
    return '兽历2026年9月1日';
  }
  if (text.startsWith('兽历')) {
    return text;
  }
  if (text.startsWith('星历')) {
    return text.replace(/^星历/, '兽历');
  }
  return `兽历${text}`;
}

/** 写入 MVU 前规范化：去掉前缀，保留 YYYY年M月D日 供 schema 存储 */
export function normalize_calendar_storage(raw: string | undefined): string {
  const text = String(raw ?? '').trim();
  if (!text) {
    return '2026年9月1日';
  }
  return text.replace(/^兽历/, '').replace(/^星历/, '');
}

export type BeastCalendarDate = {
  year: number;
  month: number;
  day: number;
};

/** 从兽历字符串解析年月日；支持「2026年9月1日」「元年9月1日」；失败返回 null */
export function parse_beast_calendar_date(raw: string | undefined): BeastCalendarDate | null {
  const text = normalize_calendar_storage(raw);
  const numeric = text.match(/(\d+)年(\d+)月(\d+)日/);
  if (numeric) {
    return {
      year: Number(numeric[1]),
      month: Number(numeric[2]),
      day: Number(numeric[3]),
    };
  }
  const eraOne = text.match(/元年(\d+)月(\d+)日/);
  if (eraOne) {
    return {
      year: 1,
      month: Number(eraOne[1]),
      day: Number(eraOne[2]),
    };
  }
  return null;
}

/** 判断兽历是否仍为开局默认值（兼容旧「星历」键与带前缀写法） */
export function is_default_opening_calendar(raw: string | undefined): boolean {
  const normalized = normalize_calendar_storage(raw);
  return normalized.startsWith('2026年9月1日');
}
