import type { Schema } from '../schema';
import { get_disbanded_squad_names } from './squadUserCommands';

type Stat = Schema;

function decode_json_pointer_segment(segment: string): string {
  return segment.replace(/~1/g, '/').replace(/~0/g, '~');
}

function squad_name_from_patch_path(path: string): string | null {
  const m = path.match(/^\/探索编队\/([^/]+)/);
  if (!m) return null;
  return decode_json_pointer_segment(m[1]);
}

function extract_json_patches_from_text(text: string): Array<{ op?: string; path?: string }> {
  const patches: Array<{ op?: string; path?: string }> = [];
  const block = text.match(/(?:<|&lt;)JSONPatch(?:>|&gt;)([\s\S]*?)(?:<|&lt;)\/JSONPatch(?:>|&gt;)/i);
  if (block?.[1]) {
    try {
      const parsed = JSON.parse(block[1].trim());
      if (Array.isArray(parsed)) {
        patches.push(...parsed);
      }
    } catch {
      /* ignore */
    }
  }
  return patches;
}

const CREATE_RE = /\[新建编队\]\s*([^，,\n]+)(?:[，,]\s*队长[：:]\s*(\S+))?/g;

/** 从 0..maxMessageId 的 AI JSONPatch 与用户 [新建编队] 收集「有依据」的编队名 */
export function collect_authorized_squad_names(max_message_id: number): Set<string> {
  const names = new Set<string>();
  if (typeof getChatMessages !== 'function' || max_message_id < 0) {
    return names;
  }

  const msgs = getChatMessages(`0-${max_message_id}`);
  for (const msg of msgs) {
    if (msg.role === 'assistant') {
      for (const patch of extract_json_patches_from_text(msg.message)) {
        const squad_name = patch.path ? squad_name_from_patch_path(patch.path) : null;
        if (!squad_name) continue;
        if (patch.op === 'remove') {
          names.delete(squad_name);
        } else if (patch.op === 'add' || patch.op === 'replace') {
          names.add(squad_name);
        }
      }
    }
    if (msg.role === 'user' && /\[新建编队\]/.test(msg.message)) {
      CREATE_RE.lastIndex = 0;
      let m: RegExpExecArray | null;
      while ((m = CREATE_RE.exec(msg.message)) !== null) {
        const name = m[1]?.trim();
        if (name) names.add(name);
      }
    }
  }

  for (const name of get_disbanded_squad_names()) {
    names.delete(name);
  }
  return names;
}

/**
 * 移除 stat 中无 JSONPatch / 玩家指令来源的编队。
 * 用于重 roll 后清掉继承或本地 merge 残留的旧编队。
 */
export function purge_unauthorized_exploration_squads(
  stat: Stat,
  max_message_id: number,
  authorized?: Set<string>,
): boolean {
  const allowed = authorized ?? collect_authorized_squad_names(max_message_id);
  let changed = false;
  for (const name of Object.keys(stat.探索编队)) {
    if (allowed.has(name)) continue;
    delete stat.探索编队[name];
    changed = true;
    console.info('[探索编队] 已移除无依据编队（重 roll/继承残留）:', name);
  }
  return changed;
}

export function resolve_latest_message_id(): number {
  try {
    return getChatMessages(-1)[0]?.message_id ?? -1;
  } catch {
    return -1;
  }
}

/** 重 roll 第 N 层后：N..latest 各楼编队只保留 0..N 层 patch/指令曾出现过的队名 */
export async function cascade_purge_squads_after_regenerate(from_message_id: number): Promise<void> {
  if (typeof Mvu === 'undefined' || typeof waitGlobalInitialized !== 'function') {
    return;
  }
  await waitGlobalInitialized('Mvu');
  const latest = resolve_latest_message_id();
  if (latest < from_message_id) {
    return;
  }
  const authorized = collect_authorized_squad_names(from_message_id);
  for (let mid = from_message_id; mid <= latest; mid++) {
    const mvu_data = Mvu.getMvuData({ type: 'message', message_id: mid });
    const stat = _.get(mvu_data, 'stat_data') as Stat | undefined;
    if (!stat || typeof stat !== 'object') continue;
    if (!purge_unauthorized_exploration_squads(stat, from_message_id, authorized)) {
      continue;
    }
    _.set(mvu_data, 'stat_data', stat);
    await Mvu.replaceMvuData(mvu_data, { type: 'message', message_id: mid });
  }
}
