import { defineMvuDataStore } from '@util/mvu';
import { Schema } from '../../schema';
import { reconcile_exploration_squads, reconcile_squad_member_exclusivity, sync_squads_from_return_story, } from './util/squadSync';
import { build_population_composition_record, should_resync_population_composition, } from './util/populationComposition';
import { unnamed_efficiency_from_cohesion } from './util/campVariableSync';
import { infer_npc_grade_from_skills } from './util/npcGrade';
import { syncFirepitWithFuel, inferCampfireFuelFromStory } from './util/campfire';
import { clampWarehouseReserves, getLatestAssistantStoryAndMessage, repairMisplacedWarehouse, syncWarehouseFromSettlementStory, } from './util/settlementSync';
import { sync_npc_action_records_from_story } from './util/npcActionRecord';
import { sync_comprehensive_affairs } from '../../util/comprehensiveAffairsSync';
import { sync_user_warehouse_deposits } from '../../util/userWarehouseSync';
import { purge_misclassified_named_npcs } from '../../util/npcPanelSync';
import { apply_user_squad_commands } from '../../util/squadUserCommands';
import { applySquadInferToStat } from '../../util/squadInferSync';
import { purge_unauthorized_exploration_squads, resolve_latest_message_id } from '../../util/squadAuthority';
import { sync_world_time_tick } from './util/worldTimeTick';
import { ensure_exploration_area_catalog } from './util/explorationAreaBackfill';
import { sync_survival_metrics } from './util/survivalMetricsSync';
import { syncAllWorkActivation } from './util/workQueue';
function sync_npc_grades_from_skills(data) {
    for (const npc of _.values(data.具名NPC)) {
        const inferred = infer_npc_grade_from_skills(npc.技能);
        if (npc.档位 !== inferred) {
            npc.档位 = inferred;
        }
    }
    for (const npc of _.values(data.未收入兽耳娘)) {
        const inferred = infer_npc_grade_from_skills(npc.技能);
        if (npc.档位 !== inferred) {
            npc.档位 = inferred;
        }
    }
}
/** 始终读取最新楼层的 stat_data，避免状态栏 iframe 所在楼层落后于开局 AI 回复楼层 */
export const useDataStore = defineMvuDataStore(Schema, { type: 'message', message_id: 'latest' }, data => {
    watchEffect(() => {
        if (data.value.世界.生存天数 < 1) {
            data.value.世界.生存天数 = 1;
        }
        const latest_id = resolve_latest_message_id();
        if (latest_id >= 0) {
            purge_unauthorized_exploration_squads(data.value, latest_id);
        }
        applySquadInferToStat(data.value);
        apply_user_squad_commands(data.value);
        sync_squads_from_return_story(data.value);
        reconcile_exploration_squads(data.value);
        reconcile_squad_member_exclusivity(data.value);
        ensure_exploration_area_catalog(data.value);
        sync_comprehensive_affairs(data.value);
        purge_misclassified_named_npcs(data.value);
        sync_user_warehouse_deposits(data.value);
        repairMisplacedWarehouse(data.value);
        const latestStory = getLatestAssistantStoryAndMessage();
        syncWarehouseFromSettlementStory(data.value, latestStory.story, {
            messageText: latestStory.message,
            messageId: latestStory.messageId,
        });
        clampWarehouseReserves(data.value);
        sync_npc_action_records_from_story(data.value, latestStory.story);
        inferCampfireFuelFromStory(data.value.营地.当前建筑, data.value.营地.篝火燃料);
        syncFirepitWithFuel(data.value.营地.当前建筑, data.value.营地.篝火燃料);
        sync_survival_metrics(data.value);
        sync_npc_grades_from_skills(data.value);
        sync_world_time_tick(data.value);
        syncAllWorkActivation(data.value);
    });
    watchEffect(() => {
        const camp = data.value.营地;
        const expected = unnamed_efficiency_from_cohesion(camp.向心力);
        if (camp.无名族人基准效率 !== expected) {
            camp.无名族人基准效率 = expected;
        }
    });
    watchEffect(() => {
        const camp = data.value.营地;
        if (!should_resync_population_composition(camp.人口, data.value.具名NPC, camp.族人构成)) {
            return;
        }
        camp.族人构成 = build_population_composition_record(camp.人口, data.value.具名NPC);
    });
});
